const i=JSON.parse('{"workId":"li-ji","chapter":{"id":"li-ji_ch-6","workId":"li-ji","order":6,"title":"月令","difficulty":4,"estimatedMinutes":22,"passageIds":["li-ji_ch-6_p-1","li-ji_ch-6_p-2","li-ji_ch-6_p-3","li-ji_ch-6_p-4","li-ji_ch-6_p-5","li-ji_ch-6_p-6","li-ji_ch-6_p-7","li-ji_ch-6_p-8","li-ji_ch-6_p-9","li-ji_ch-6_p-10","li-ji_ch-6_p-11","li-ji_ch-6_p-12","li-ji_ch-6_p-13","li-ji_ch-6_p-14","li-ji_ch-6_p-15","li-ji_ch-6_p-16","li-ji_ch-6_p-17","li-ji_ch-6_p-18","li-ji_ch-6_p-19","li-ji_ch-6_p-20","li-ji_ch-6_p-21","li-ji_ch-6_p-22","li-ji_ch-6_p-23","li-ji_ch-6_p-24","li-ji_ch-6_p-25","li-ji_ch-6_p-26","li-ji_ch-6_p-27","li-ji_ch-6_p-28","li-ji_ch-6_p-29","li-ji_ch-6_p-30","li-ji_ch-6_p-31","li-ji_ch-6_p-32","li-ji_ch-6_p-33","li-ji_ch-6_p-34","li-ji_ch-6_p-35","li-ji_ch-6_p-36","li-ji_ch-6_p-37","li-ji_ch-6_p-38","li-ji_ch-6_p-39","li-ji_ch-6_p-40","li-ji_ch-6_p-41","li-ji_ch-6_p-42","li-ji_ch-6_p-43","li-ji_ch-6_p-44","li-ji_ch-6_p-45","li-ji_ch-6_p-46","li-ji_ch-6_p-47","li-ji_ch-6_p-48","li-ji_ch-6_p-49","li-ji_ch-6_p-50","li-ji_ch-6_p-51","li-ji_ch-6_p-52","li-ji_ch-6_p-53","li-ji_ch-6_p-54","li-ji_ch-6_p-55","li-ji_ch-6_p-56","li-ji_ch-6_p-57","li-ji_ch-6_p-58","li-ji_ch-6_p-59","li-ji_ch-6_p-60","li-ji_ch-6_p-61","li-ji_ch-6_p-62","li-ji_ch-6_p-63","li-ji_ch-6_p-64","li-ji_ch-6_p-65","li-ji_ch-6_p-66","li-ji_ch-6_p-67","li-ji_ch-6_p-68","li-ji_ch-6_p-69","li-ji_ch-6_p-70","li-ji_ch-6_p-71","li-ji_ch-6_p-72","li-ji_ch-6_p-73","li-ji_ch-6_p-74","li-ji_ch-6_p-75","li-ji_ch-6_p-76","li-ji_ch-6_p-77","li-ji_ch-6_p-78","li-ji_ch-6_p-79","li-ji_ch-6_p-80","li-ji_ch-6_p-81","li-ji_ch-6_p-82","li-ji_ch-6_p-83","li-ji_ch-6_p-84","li-ji_ch-6_p-85","li-ji_ch-6_p-86","li-ji_ch-6_p-87","li-ji_ch-6_p-88","li-ji_ch-6_p-89","li-ji_ch-6_p-90","li-ji_ch-6_p-91","li-ji_ch-6_p-92","li-ji_ch-6_p-93","li-ji_ch-6_p-94","li-ji_ch-6_p-95","li-ji_ch-6_p-96","li-ji_ch-6_p-97","li-ji_ch-6_p-98","li-ji_ch-6_p-99","li-ji_ch-6_p-100","li-ji_ch-6_p-101","li-ji_ch-6_p-102","li-ji_ch-6_p-103","li-ji_ch-6_p-104","li-ji_ch-6_p-105","li-ji_ch-6_p-106","li-ji_ch-6_p-107","li-ji_ch-6_p-108","li-ji_ch-6_p-109"],"tags":["儒家","禮樂"]},"passages":[{"id":"li-ji_ch-6_p-1","chapterId":"li-ji_ch-6","order":1,"canonicalText":"孟春之月，日在營室，昏參中，旦尾中。其日甲乙。其帝大皞，其神句芒。其蟲鱗。其音角，律中大蔟。其數八。其味酸，其臭羶。其祀戶，祭先脾。","sentenceIds":["li-ji_ch-6_p-1_s-1","li-ji_ch-6_p-1_s-2","li-ji_ch-6_p-1_s-3","li-ji_ch-6_p-1_s-4","li-ji_ch-6_p-1_s-5","li-ji_ch-6_p-1_s-6","li-ji_ch-6_p-1_s-7","li-ji_ch-6_p-1_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"月令篇記孟春之月：日在營室，昏參中，旦尾中；天地萌動，陽氣升騰；天子親率公卿藉田以勸農桑，祭告先農，宣示一年春耕教化之始。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 1 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「孟春之月，日在營室，昏參中，旦尾中」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「孟春之月，日在營室，昏參中，旦尾中。其日甲乙。其帝大……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-2","chapterId":"li-ji_ch-6","order":2,"canonicalText":"東風解凍，蟄蟲始振，魚上冰，獺祭魚，鴻雁來。","sentenceIds":["li-ji_ch-6_p-2_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟春正月，東風拂面大地消融解凍，冬眠蟄伏的昆蟲開始甦醒蠕動，魚兒游到未融的冰面下游動，水獺捕獲魚兒陳列水岸如同祭拜，大雁自南方振翅北歸。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 2 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「東風解凍，蟄蟲始振，魚上冰，獺祭魚，鴻雁來」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「東風解凍，蟄蟲始振，魚上冰，獺祭魚，鴻雁來。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-3","chapterId":"li-ji_ch-6","order":3,"canonicalText":"天子居青陽左個。乘鸞路，駕倉龍，載青旗，衣青衣，服倉玉，食麥與羊，其器疏以達。","sentenceIds":["li-ji_ch-6_p-3_s-1","li-ji_ch-6_p-3_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟春正月之時，天子居住在明堂東側的「青陽左個」（東北偏室）。乘坐飾有鸞鈴的青色「鸞路」車駕，駕馭青黑色的青龍駿馬，車上插設繪有龍紋的青色旗幟，身穿青色朝服，佩戴青色蒼玉，進食麥飯與羊肉，所使用的各類祭器與生活器具，器形雕飾皆疏朗通透、鏤空通暢，以順應春季陽氣條達舒展之生機。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 3 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天子居青陽左個」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天子居青陽左個。乘鸞路，駕倉龍，載青旗，衣青衣，服倉……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-4","chapterId":"li-ji_ch-6","order":4,"canonicalText":"是月也，以立春。先立春三日，大史謁之天子曰：某日立春，盛德在木。天子乃齊。立春之日，天子親帥三公、九卿、諸侯、大夫以迎春於東郊。還反，賞公卿、諸侯、大夫於朝。命相佈德和令，行慶施惠，下及兆民。慶賜遂行，毋有不當。乃命大史守典奉法，司天日月星辰之行，宿離不貸，毋失經紀，以初為常。","sentenceIds":["li-ji_ch-6_p-4_s-1","li-ji_ch-6_p-4_s-2","li-ji_ch-6_p-4_s-3","li-ji_ch-6_p-4_s-4","li-ji_ch-6_p-4_s-5","li-ji_ch-6_p-4_s-6","li-ji_ch-6_p-4_s-7","li-ji_ch-6_p-4_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，以立春。先立春三日，大史謁的天孔子先生親自開示教導說道：某日立春，盛崇高德行與品性修養在木。天子乃齊。立春的日，天子親帥三公、九卿、諸侯、卿大夫貴族官員以迎春於東郊。還反，賞公卿、諸侯、卿大夫貴族官員於朝。命相佈崇高德行與品性修養和令，行慶施惠，下及兆民。慶賜遂行，毋有不當。乃命大史守典奉法，司天日月星辰的行，宿離不貸，毋失經紀，以初為常。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 4 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，以立春」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，以立春。先立春三日，大史謁之天子曰：某日立春……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-5","chapterId":"li-ji_ch-6","order":5,"canonicalText":"是月也，天子乃以元日祈穀於上帝。乃擇元辰，天子親載耒耜，措之參保介之御間，帥三公、九卿、諸侯、大夫，躬耕帝藉。天子三推，三公五推，卿諸侯九推。反，執爵於大寢，三公、九卿、諸侯、大夫皆御，命曰：勞酒。","sentenceIds":["li-ji_ch-6_p-5_s-1","li-ji_ch-6_p-5_s-2","li-ji_ch-6_p-5_s-3","li-ji_ch-6_p-5_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟春之政：命樂正習舞，修整鐘鼓琴瑟；禁伐木，無覆巢，殺胎夭，保護幼獸雛鳥，以順天地發生之氣。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 5 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，天子乃以元日祈穀於上帝」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，天子乃以元日祈穀於上帝。乃擇元辰，天子親載耒……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-6","chapterId":"li-ji_ch-6","order":6,"canonicalText":"是月也，天氣下降，地氣上騰，天地和同，草木萌動。王命布農事，命田舍東郊，皆修封疆，審端經術。善相丘陵阪險原隰土地所宜，五穀所殖，以教道民，必躬親之。田事既飭，先定準直，農乃不惑。","sentenceIds":["li-ji_ch-6_p-6_s-1","li-ji_ch-6_p-6_s-2","li-ji_ch-6_p-6_s-3","li-ji_ch-6_p-6_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，天之陽氣自上向下交降，地之陰氣自下向上蒸騰，天地二氣陰陽融洽和順，大地草木開始萌發滋長。天子向天下頒布春耕農事政令，命農官在東郊祭神之後宿居於農野田舍，全面修整田間的疆界封埒，嚴格端正劃定經緯阡陌。仔細勘察丘陵高地、坡阪險阻、平原低窪與沼澤濕地等各類土地的水土所宜，辨別各宜種植何種五穀作物，以此親自教授開導萬民農耕之方，君王官吏必須躬親視察督導。田野農事整備齊全，預先確立立表測影與水準引繩的準直標準，使農民耕墾播種心中有所遵循而不致迷惑紊亂。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 6 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，天氣下降，地氣上騰，天地和同，草木萌動」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，天氣下降，地氣上騰，天地和同，草木萌動。王命……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-7","chapterId":"li-ji_ch-6","order":7,"canonicalText":"是月也，命樂正入學習舞。乃修祭典。命祀山林川澤，犧牲毋用牝。禁止伐木。毋覆巢，毋殺孩蟲、胎、夭、飛鳥。毋麑，毋卵。毋聚大眾，毋置城郭。掩骼埋胔。","sentenceIds":["li-ji_ch-6_p-7_s-1","li-ji_ch-6_p-7_s-2","li-ji_ch-6_p-7_s-3","li-ji_ch-6_p-7_s-4","li-ji_ch-6_p-7_s-5","li-ji_ch-6_p-7_s-6","li-ji_ch-6_p-7_s-7","li-ji_ch-6_p-7_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，命令樂正官率領貴族子弟進入學宮學習樂舞。隨後修葺整理祭祀典章禮樂。命有司祭祀境內名山、大林、名川與巨澤之神，祭祀所用的牲畜不得使用雌性母畜以護佑繁育。嚴厲禁止採伐山林林木。不可傾覆毀壞樹上的鳥巢，不可捕殺幼小的昆蟲幼蟲、懷孕母獸、初生幼獸以及初飛雛鳥。不可獵殺幼鹿，不可搜取鳥卵。朝廷不得徵集大規模徭役聚眾，不可大興土木築造城郭。全面巡行野外，掩埋暴露在荒野中的人畜骨骸與腐肉枯尸，以示順應仁愛生發之氣。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 7 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，命樂正入學習舞」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，命樂正入學習舞。乃修祭典。命祀山林川澤，犧牲……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-8","chapterId":"li-ji_ch-6","order":8,"canonicalText":"是月也，不可以稱兵，稱兵必天殃。兵戎不起，不可從我始。毋變天之道，毋絕地之理，毋亂人之紀。","sentenceIds":["li-ji_ch-6_p-8_s-1","li-ji_ch-6_p-8_s-2","li-ji_ch-6_p-8_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，不可以稱兵，稱兵必天殃。兵戎不起，不可從我始。毋變天的道，毋絕地的理，毋亂人的紀。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 8 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，不可以稱兵，稱兵必天殃」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，不可以稱兵，稱兵必天殃。兵戎不起，不可從我始……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-9","chapterId":"li-ji_ch-6","order":9,"canonicalText":"孟春行夏令，則雨水不時，草木蚤落，國時有恐。行秋令則其民大疫，猋風暴雨總至，藜莠蓬蒿並興。行冬令則水潦為敗，雪霜大摯，首種不入。","sentenceIds":["li-ji_ch-6_p-9_s-1","li-ji_ch-6_p-9_s-2","li-ji_ch-6_p-9_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟春正月若是推行了夏季的政令，就會導致降雨違失農時，草木過早凋零落葉，國家境內常常發生驚恐騷亂之事。若是推行了秋季的政令，百姓就會流行大疫瘟疫，疾風暴雨狂作齊至，藜莠蓬蒿等各類惡性雜草與莊稼一同瘋長。若是推行了冬季的政令，就會引發洪澇澇災敗壞田畝，暴雪嚴霜嚴重殘害禾苗，春季首批播種的穀物顆粒無收無法入倉。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 9 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「孟春行夏令，則雨水不時，草木蚤落，國時有恐」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「孟春行夏令，則雨水不時，草木蚤落，國時有恐。行秋令則……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-10","chapterId":"li-ji_ch-6","order":10,"canonicalText":"仲春之月，日在奎，昏弧中，旦建星中。其日甲乙，其帝大皞，其神句芒。其蟲鱗。其音角，律中夾鐘。其數八。其味酸，其臭羶，其祀戶，祭先脾。","sentenceIds":["li-ji_ch-6_p-10_s-1","li-ji_ch-6_p-10_s-2","li-ji_ch-6_p-10_s-3","li-ji_ch-6_p-10_s-4","li-ji_ch-6_p-10_s-5","li-ji_ch-6_p-10_s-6"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲春之月：玄鳥至，雷乃發聲，始電；日夜分，同度量，審鈞石，角斗甬，正權概，以平天下之商賈。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 10 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「仲春之月，日在奎，昏弧中，旦建星中」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「仲春之月，日在奎，昏弧中，旦建星中。其日甲乙，其帝大……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-11","chapterId":"li-ji_ch-6","order":11,"canonicalText":"始雨水，桃始華，倉庚鳴，鷹化為鳩。","sentenceIds":["li-ji_ch-6_p-11_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟春之月，天空開始降下雨水，桃花初次綻放盛開，黃鶯在林間婉轉啼鳴，凶猛的蒼鷹退隱林泉，溫馴的斑鳩化育繁衍。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 11 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「始雨水，桃始華，倉庚鳴，鷹化為鳩」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「始雨水，桃始華，倉庚鳴，鷹化為鳩。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-12","chapterId":"li-ji_ch-6","order":12,"canonicalText":"天子居青陽大廟，乘鸞路，駕倉龍，載青旗，衣青衣，服倉玉，食麥與羊，其器疏以達。","sentenceIds":["li-ji_ch-6_p-12_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲春二月之時，天子居住在明堂東面的正堂「青陽大廟」之中。乘坐飾有鸞鈴的青色鸞路車駕，駕馭純青駿馬，車上載設青色旗幟，身穿青色朝服，佩戴青色蒼玉，進食麥米與羊肉，所使用的各類器具雕琢皆疏朗通達，以順應陽氣發揚通暢之象。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 12 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天子居青陽大廟，乘鸞路，駕倉龍，載青旗，衣青衣，服倉玉，食麥與羊，其器疏以達」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天子居青陽大廟，乘鸞路，駕倉龍，載青旗，衣青衣，服倉……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-13","chapterId":"li-ji_ch-6","order":13,"canonicalText":"是月也，安萌芽，養幼少，存諸孤。擇元日，命民社。命有司省囹圄，去桎梏，毋肆掠，止獄訟。","sentenceIds":["li-ji_ch-6_p-13_s-1","li-ji_ch-6_p-13_s-2","li-ji_ch-6_p-13_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，應當妥善護理植物的新生萌芽，細心撫育幼小的禽獸，撫恤撫養民間各類孤兒幼弱。挑選吉利的元日吉辰，命令百姓聚集舉行祭祀土地神之「民社」盛會。命令司法官員巡視清理牢獄監房，除掉刑徒身上的桎梏刑具，禁止官吏肆意拷打掠笞囚犯，調停制止各類爭訟與詞訟獄事。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 13 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，安萌芽，養幼少，存諸孤」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，安萌芽，養幼少，存諸孤。擇元日，命民社。命有……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-14","chapterId":"li-ji_ch-6","order":14,"canonicalText":"是月也，玄鳥至。至之日，以大牢祠於高禖。天子親往，后妃帥九嬪御。乃禮天子所御，帶以弓韣，授以弓矢，於高禖之前。","sentenceIds":["li-ji_ch-6_p-14_s-1","li-ji_ch-6_p-14_s-2","li-ji_ch-6_p-14_s-3","li-ji_ch-6_p-14_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，玄鳥至。至的日，以大牢祠於高禖。天子親往，后妃帥九嬪御。乃禮儀規程與道崇高德行與品性修養規範天子所御，帶以弓韣，授以弓矢，於高禖的前。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 14 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，玄鳥至」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，玄鳥至。至之日，以大牢祠於高禖。天子親往，後……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-15","chapterId":"li-ji_ch-6","order":15,"canonicalText":"是月也，日夜分。雷乃發聲，始電，蟄蟲鹹動，啟戶始出。先雷三日，奮木鐸以令兆民曰：雷將發聲，有不戒其容止者，生子不備，必有兇災。日夜分，則同度量，鈞衡石，角鬥甬，正權概。","sentenceIds":["li-ji_ch-6_p-15_s-1","li-ji_ch-6_p-15_s-2","li-ji_ch-6_p-15_s-3","li-ji_ch-6_p-15_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季春之月：桐始華，田鼠化為鴽，虹始見；天子薦鞠衣於先妣，乃修蠶事，迎夏氣於南郊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 15 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，日夜分」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，日夜分。雷乃發聲，始電，蟄蟲鹹動，啟戶始出。……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-16","chapterId":"li-ji_ch-6","order":16,"canonicalText":"是月也，耕者少舍。乃修闔扇，寢廟畢備。毋作大事，以妨農之事。","sentenceIds":["li-ji_ch-6_p-16_s-1","li-ji_ch-6_p-16_s-2","li-ji_ch-6_p-16_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，耕的人或禮儀規程與道崇高德行與品性修養規範制規範少舍。乃修闔扇，寢廟畢備。毋作大事，以妨農的事。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 16 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，耕者少舍」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，耕者少舍。乃修闔扇，寢廟畢備。毋作大事，以妨……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-17","chapterId":"li-ji_ch-6","order":17,"canonicalText":"是月也，毋竭川澤，毋漉陂池，毋焚山林。天子乃鮮羔開冰，先薦寢廟。上丁，命樂正習舞，釋菜。天子乃帥三公、九卿、諸侯、大夫親往視之。仲丁，又命樂正入學習舞。","sentenceIds":["li-ji_ch-6_p-17_s-1","li-ji_ch-6_p-17_s-2","li-ji_ch-6_p-17_s-3","li-ji_ch-6_p-17_s-4","li-ji_ch-6_p-17_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，毋竭川澤，毋漉陂池，毋焚山林。天子乃鮮羔開冰，先薦寢廟。上丁，命雅樂和聲與心靈感化正習舞，釋菜。天子乃帥三公、九卿、諸侯、卿大夫貴族官員親往視的。仲丁，又命雅樂和聲與心靈感化正入學習舞。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 17 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，毋竭川澤，毋漉陂池，毋焚山林」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，毋竭川澤，毋漉陂池，毋焚山林。天子乃鮮羔開冰……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-18","chapterId":"li-ji_ch-6","order":18,"canonicalText":"是月也，祀不用犧牲，用圭璧，更皮幣。","sentenceIds":["li-ji_ch-6_p-18_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，祀不用犧牲，用圭璧，更皮幣。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 18 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，祀不用犧牲，用圭璧，更皮幣」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，祀不用犧牲，用圭璧，更皮幣。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-19","chapterId":"li-ji_ch-6","order":19,"canonicalText":"仲春行秋令，則其國大水，寒氣總至，寇戎來徵。行冬令，則陽氣不勝，麥乃不熟，民多相掠。行夏令，則國乃大旱，暖氣早來，蟲螟為害。","sentenceIds":["li-ji_ch-6_p-19_s-1","li-ji_ch-6_p-19_s-2","li-ji_ch-6_p-19_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲春二月若是推行了秋季的政令，其國家就會遭遇滔天大水洪澇，肅殺寒氣隨之全面襲來，四方戎狄寇賊就會趁機發兵侵略征伐。若是推行了冬季的政令，天地陽氣受到遏抑而不得舒展，麥子便無法結實成熟，民間饑荒缺糧以致百姓四處相互搶奪掠奪。若是推行了夏季的政令，國家便會遭遇嚴重旱災，酷熱暑氣過早降臨，螟蟲等各類害蟲肆虐成災為害莊稼。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 19 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「仲春行秋令，則其國大水，寒氣總至，寇戎來徵」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「仲春行秋令，則其國大水，寒氣總至，寇戎來徵。行冬令，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-20","chapterId":"li-ji_ch-6","order":20,"canonicalText":"季春之月，日在胃，昏七星中，旦牽牛中。其日甲乙。其帝大皞，其神句芒。其蟲鱗。其音角，律中姑洗。其數八。其味酸，其臭羶。其祀戶，祭先脾。","sentenceIds":["li-ji_ch-6_p-20_s-1","li-ji_ch-6_p-20_s-2","li-ji_ch-6_p-20_s-3","li-ji_ch-6_p-20_s-4","li-ji_ch-6_p-20_s-5","li-ji_ch-6_p-20_s-6","li-ji_ch-6_p-20_s-7","li-ji_ch-6_p-20_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟夏之月：日在畢，迎夏氣；螻蟈鳴，蚯蚓出，王瓜生，苦菜秀；斷薄刑，決小罪，行寬大之政以順夏木盛長。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 20 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「季春之月，日在胃，昏七星中，旦牽牛中」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「季春之月，日在胃，昏七星中，旦牽牛中。其日甲乙。其帝……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-21","chapterId":"li-ji_ch-6","order":21,"canonicalText":"桐始華，田鼠化為鴽，虹始見，萍始生。","sentenceIds":["li-ji_ch-6_p-21_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季春三月，梧桐樹開始繁花盛放，喜陰的田鼠匿跡而鵪鶉類的春鳥飛鳴，雨後天際初次顯現彩虹，池沼水面浮萍開始叢生。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 21 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「桐始華，田鼠化為鴽，虹始見，萍始生」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「桐始華，田鼠化為鴽，虹始見，萍始生。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-22","chapterId":"li-ji_ch-6","order":22,"canonicalText":"天子居青陽右個，乘鸞路，駕倉龍，載青旗，衣青衣，服倉玉。食麥與羊，其器疏以達。","sentenceIds":["li-ji_ch-6_p-22_s-1","li-ji_ch-6_p-22_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季春三月之時，天子居住在明堂東南側的「青陽右個」偏室之中。乘坐飾有鸞鈴的青色鸞路車駕，駕馭純青駿馬，車上載設青旗，身穿青色禮服，佩戴青色蒼玉。進食麥飯與羊肉，所使用的器具皆鏤空疏朗而通達通透。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 22 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天子居青陽右個，乘鸞路，駕倉龍，載青旗，衣青衣，服倉玉」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天子居青陽右個，乘鸞路，駕倉龍，載青旗，衣青衣，服倉……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-23","chapterId":"li-ji_ch-6","order":23,"canonicalText":"是月也，天子乃薦鞠衣於先帝。命舟牧覆舟，五覆五反。乃告舟備具於天子焉，天子始乘舟。薦鮪於寢廟，乃為麥祈實。","sentenceIds":["li-ji_ch-6_p-23_s-1","li-ji_ch-6_p-23_s-2","li-ji_ch-6_p-23_s-3","li-ji_ch-6_p-23_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，天子在宗廟之中向先帝先王進獻蠶桑典禮所用的「鞠衣」黃色禮服。命令掌管舟船的官吏「舟牧」反覆檢驗翻覆船隻五次以測試船身防漏抗沉能力。舟牧向天子稟報各類船隻已經修繕具備，天子才開始乘船出遊巡幸水波。在寢廟中向祖先薦獻時令新捕的肥美鱘鮪魚，並舉行祭祀為麥類作物的結實豐收祈禱。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 23 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，天子乃薦鞠衣於先帝」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，天子乃薦鞠衣於先帝。命舟牧覆舟，五覆五反。乃……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-24","chapterId":"li-ji_ch-6","order":24,"canonicalText":"是月也，生氣方盛，陽氣發泄，句者畢出，萌者盡達。不可以內。天子佈德行惠，命有司發倉廩，賜貧窮，振乏絕，開府庫，出幣帛，周天下。勉諸侯，聘名士，禮賢者。","sentenceIds":["li-ji_ch-6_p-24_s-1","li-ji_ch-6_p-24_s-2","li-ji_ch-6_p-24_s-3","li-ji_ch-6_p-24_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，生氣方盛，陽氣發泄，句的人或禮儀規程與道崇高德行與品性修養規範制規範畢出，萌的人或禮儀規程與道崇高德行與品性修養規範制規範盡達。不可以內。天子佈崇高德行與品性修養行惠，命有司發倉廩，賜貧窮，振乏絕，開府庫，出幣帛，周天下。勉諸侯，聘名士人階層，禮儀規程與道崇高德行與品性修養規範賢的人或禮儀規程與道崇高德行與品性修養規範制規範。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 24 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，生氣方盛，陽氣發泄，句者畢出，萌者盡達」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，生氣方盛，陽氣發泄，句者畢出，萌者盡達。不可……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-25","chapterId":"li-ji_ch-6","order":25,"canonicalText":"是月也，命司空曰：時雨將降，下水上騰，循行國邑，周視原野，修利堤防，道達溝瀆，開通道路，毋有障塞。田獵罝罘、羅網、畢翳、餧獸之藥，毋出九門。","sentenceIds":["li-ji_ch-6_p-25_s-1","li-ji_ch-6_p-25_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲夏之月：日長至，陰陽爭，死生分；君子齊戒處必掩身，薄滋味，無生嗜慾，抑陰爭陽，以安五臟。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 25 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，命司空曰：時雨將降，下水上騰，循行國邑，周視原野，修利堤防，道達溝瀆，開通道路，毋有障塞」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，命司空曰：時雨將降，下水上騰，循行國邑，周視……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-26","chapterId":"li-ji_ch-6","order":26,"canonicalText":"是月也，命野虞毋伐桑柘。鳴鳩拂其羽，戴勝降於桑。具曲植籧筐。后妃齊戒，親東鄉躬桑。禁婦女毋觀，省婦使以勸蠶事。蠶事既登，分繭稱絲效功，以共郊廟之服，無有敢惰。","sentenceIds":["li-ji_ch-6_p-26_s-1","li-ji_ch-6_p-26_s-2","li-ji_ch-6_p-26_s-3","li-ji_ch-6_p-26_s-4","li-ji_ch-6_p-26_s-5","li-ji_ch-6_p-26_s-6"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，命令掌管野嶺林木的「野虞」官員，嚴禁任何人砍伐桑樹與柘樹。此時鳴鳩布穀鳥撲打翅膀鳴叫，戴勝鳥降落在桑樹枝頭。婦女們開始整理備辦蠶箔養蠶木架與各類竹席籧筐。王后與后妃嚴格齋戒，親自面朝東方登上蠶桑之壇採摘桑葉。禁止一般民間婦女前往觀望嬉笑，裁減宮中婦女的雜役差使，以專心勸勉推進蠶桑事業。春蠶收成繭絲成熟之後，宮中按等級分發蠶繭、過秤稱量蠶絲重量並考核工績，以此織造供給祭祀天地郊廟所用的神聖祭服，沒有人敢於稍有怠惰懈慢。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 26 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，命野虞毋伐桑柘」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，命野虞毋伐桑柘。鳴鳩拂其羽，戴勝降於桑。具曲……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-27","chapterId":"li-ji_ch-6","order":27,"canonicalText":"是月也，命工師令百工審五庫之量：金鐵，皮革筋，角齒，羽箭幹，脂膠丹漆，毋或不良。百工鹹理，監工日號；毋悖於時，毋或作為淫巧以蕩上心。","sentenceIds":["li-ji_ch-6_p-27_s-1","li-ji_ch-6_p-27_s-2","li-ji_ch-6_p-27_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，命令百工之長「工師」告誡百工官巧，嚴格審驗「五庫」所貯存原料的質量度數：金銀銅鐵等金屬、皮革獸筋、犀角象齒、羽毛箭桿木材、各類油脂膠質與丹砂清漆等，務必確保每一種物料都精良無瑕，不可稍有劣品充數。百工營造各守其法理，監工官吏每日清晨發布號令巡察督促；製作百物不得違背時令規律，更嚴禁私自製造巧偽怪誕的「淫巧」之物以惑亂放蕩君上的心智。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 27 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，命工師令百工審五庫之量：金鐵，皮革筋，角齒，羽箭幹，脂膠丹漆，毋或不良」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，命工師令百工審五庫之量：金鐵，皮革筋，角齒，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-28","chapterId":"li-ji_ch-6","order":28,"canonicalText":"是月之末，擇吉日，大合樂，天子乃率三公、九卿、諸侯、大夫親往視之。","sentenceIds":["li-ji_ch-6_p-28_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月的末，擇吉日，大合雅樂和聲與心靈感化，天子乃率三公、九卿、諸侯、卿大夫貴族官員親往視的。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 28 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月之末，擇吉日，大合樂，天子乃率三公、九卿、諸侯、大夫親往視之」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月之末，擇吉日，大合樂，天子乃率三公、九卿、諸侯、……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-29","chapterId":"li-ji_ch-6","order":29,"canonicalText":"是月也，乃合累牛騰馬，遊牝於牧。犧牲駒犢，舉，書其數。命國難，九門磔攘，以畢春氣。","sentenceIds":["li-ji_ch-6_p-29_s-1","li-ji_ch-6_p-29_s-2","li-ji_ch-6_p-29_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，乃合累牛騰馬，遊牝於牧。犧牲駒犢，舉，書他的數。命國難，九門磔攘，以畢春氣。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 29 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，乃合累牛騰馬，遊牝於牧」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，乃合累牛騰馬，遊牝於牧。犧牲駒犢，舉，書其數……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-30","chapterId":"li-ji_ch-6","order":30,"canonicalText":"季春行冬令，則寒氣時發，草木皆肅，國有大恐。行夏令，則民多疾疫，時雨不降，山林不收。行秋令，則天多沉陰，淫雨蚤降，兵革並起。","sentenceIds":["li-ji_ch-6_p-30_s-1","li-ji_ch-6_p-30_s-2","li-ji_ch-6_p-30_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季夏之月：大雨時行，土潤溽暑，濕熱交蒸；天子乃命漁師伐蛟取鼉，登龜取黿，備四時宗廟之用。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 30 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「季春行冬令，則寒氣時發，草木皆肅，國有大恐」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「季春行冬令，則寒氣時發，草木皆肅，國有大恐。行夏令，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-31","chapterId":"li-ji_ch-6","order":31,"canonicalText":"孟夏之月，日在畢，昏翼中，旦婺女中。其日丙丁。其帝炎帝，其神祝融。其蟲羽。其音徵，律中中呂。其數七。其味苦，其臭焦。其祀竈，祭先肺。","sentenceIds":["li-ji_ch-6_p-31_s-1","li-ji_ch-6_p-31_s-2","li-ji_ch-6_p-31_s-3","li-ji_ch-6_p-31_s-4","li-ji_ch-6_p-31_s-5","li-ji_ch-6_p-31_s-6","li-ji_ch-6_p-31_s-7","li-ji_ch-6_p-31_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟夏的月，日在畢，昏翼中，旦婺女中。他的日丙丁。他的帝炎帝，他的神祝融。他的蟲羽。他的音徵，律中中呂。他的數七。他的味苦，他的臭焦。他的祀竈，祭先肺。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 31 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「孟夏之月，日在畢，昏翼中，旦婺女中」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「孟夏之月，日在畢，昏翼中，旦婺女中。其日丙丁。其帝炎……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-32","chapterId":"li-ji_ch-6","order":32,"canonicalText":"螻蟈鳴，蚯螾出，王瓜生，苦菜秀。","sentenceIds":["li-ji_ch-6_p-32_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟夏四月，螻蛄與青蛙歡快鳴叫，蚯蚓鑽出潮濕泥土，王瓜蔓延抽藤結實，苦菜繁茂開花結籽。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 32 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「螻蟈鳴，蚯螾出，王瓜生，苦菜秀」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「螻蟈鳴，蚯螾出，王瓜生，苦菜秀。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-33","chapterId":"li-ji_ch-6","order":33,"canonicalText":"天子居明堂左個，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤玉。食菽與雞，其器高以粗。","sentenceIds":["li-ji_ch-6_p-33_s-1","li-ji_ch-6_p-33_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟夏四月之時，天子居住在明堂南側的「明堂左個」（東南偏室）。乘坐塗抹赤漆的朱色「朱路」車駕，駕馭赤身黑鬣的赤騮烈馬，車上插設赤紅旗幟，身穿朱紅色朝服，佩戴赤色紅玉。進食大豆大麥與雞肉，所使用的各類器具器形崇高而刻鏤質樸粗獷，以順應夏季陽氣充盛盛大之勢。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 33 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天子居明堂左個，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤玉」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天子居明堂左個，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-34","chapterId":"li-ji_ch-6","order":34,"canonicalText":"是月也，以立夏。先立夏三日，大史謁之天子曰：某日立夏，盛德在火。天子乃齊。立夏之日，天子親帥三公、九卿、大夫以迎夏於南郊。還反，行賞，封諸侯。慶賜遂行，無不欣說。乃命樂師，習合禮樂。命太尉，贊桀俊，遂賢良，舉長大，行爵出祿，必當其位。","sentenceIds":["li-ji_ch-6_p-34_s-1","li-ji_ch-6_p-34_s-2","li-ji_ch-6_p-34_s-3","li-ji_ch-6_p-34_s-4","li-ji_ch-6_p-34_s-5","li-ji_ch-6_p-34_s-6","li-ji_ch-6_p-34_s-7","li-ji_ch-6_p-34_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，以立夏。先立夏三日，大史謁的天孔子先生親自開示教導說道：某日立夏，盛崇高德行與品性修養在火。天子乃齊。立夏的日，天子親帥三公、九卿、卿大夫貴族官員以迎夏於南郊。還反，行賞，封諸侯。慶賜遂行，無不欣說。乃命雅樂和聲與心靈感化師，習合禮儀規程與道崇高德行與品性修養規範雅樂和聲與心靈感化。命太尉，贊桀俊，遂賢良，舉長大，行爵出祿，必當他的位。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 34 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，以立夏」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，以立夏。先立夏三日，大史謁之天子曰：某日立夏……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-35","chapterId":"li-ji_ch-6","order":35,"canonicalText":"是月也，繼長增高，毋有壞墮，毋起土功，毋發大眾，毋伐大樹。","sentenceIds":["li-ji_ch-6_p-35_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟秋之月：涼風至，白露降，寒蟬鳴；鷹乃祭鳥，用始行戮；天子親率三軍行秋狩獵之禮，陳設兵甲以習戰事。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 35 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，繼長增高，毋有壞墮，毋起土功，毋發大眾，毋伐大樹」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，繼長增高，毋有壞墮，毋起土功，毋發大眾，毋伐……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-36","chapterId":"li-ji_ch-6","order":36,"canonicalText":"是月也，天子始絺。命野虞出行田原，為天子勞農勸民，毋或失時。命司徒巡行縣鄙，命農勉作，毋休于都。","sentenceIds":["li-ji_ch-6_p-36_s-1","li-ji_ch-6_p-36_s-2","li-ji_ch-6_p-36_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，天氣漸熱，天子開始換穿清涼舒爽的細葛布夏衣「絺」。命令掌管山野林地的野虞官吏巡行巡視田疇平原，代表天子慰勞犒賞農民、勸勉百姓勤於農稼，切切不可耽誤失誤了夏收夏種的農時。命令大司徒巡視考察鄉縣偏鄙之境，嚴厲督促農民努力耘鋤勞作，不可無故滯留閒遊於都市城鎮之中。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 36 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，天子始絺」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，天子始絺。命野虞出行田原，為天子勞農勸民，毋……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-37","chapterId":"li-ji_ch-6","order":37,"canonicalText":"是月也，驅獸毋害五穀，毋大田獵。農乃登麥，天子乃以彘嘗麥，先薦寢廟。","sentenceIds":["li-ji_ch-6_p-37_s-1","li-ji_ch-6_p-37_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，組織驅逐驅趕野獸，嚴防野獸踐踏損害田間五穀，但嚴禁舉行大規模合圍田獵以戕害生機。農田裡的夏麥開始收割登場，天子用肥豬為犧牲舉行嘗麥新禮，首先將新麥薦獻於先王祖廟寢殿之中。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 37 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，驅獸毋害五穀，毋大田獵」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，驅獸毋害五穀，毋大田獵。農乃登麥，天子乃以彘……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-38","chapterId":"li-ji_ch-6","order":38,"canonicalText":"是月也，聚畜百藥。靡草死，麥秋至。斷薄刑，決小罪，出輕系。蠶事畢，后妃獻繭。乃收繭稅，以桑為均，貴賤長幼如一，以給郊廟之服。","sentenceIds":["li-ji_ch-6_p-38_s-1","li-ji_ch-6_p-38_s-2","li-ji_ch-6_p-38_s-3","li-ji_ch-6_p-38_s-4","li-ji_ch-6_p-38_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，採集儲備各類百草藥材以供醫療疾疫之用。感應陰氣而生的細弱靡草枯萎死絕，麥熟之候的「麥秋」正式到來。朝廷審斷較輕的薄刑，裁決告結微小的罪過，釋放輕罪羈押的拘留犯人。民間蠶桑之事已經結束，王后率領命婦向天子獻納蠶繭。官府隨後開始徵收民間的蠶繭之稅，以桑樹的株數多寡作為均攤標準，無論貴族平民、年長幼小皆一視同仁按律徵收，用以織造供給祭祀天地郊廟的祭服。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 38 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，聚畜百藥」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，聚畜百藥。靡草死，麥秋至。斷薄刑，決小罪，出……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-39","chapterId":"li-ji_ch-6","order":39,"canonicalText":"是月也，天子飲酎，用禮樂。","sentenceIds":["li-ji_ch-6_p-39_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，天子飲酎，用禮儀規程與道崇高德行與品性修養規範雅樂和聲與心靈感化。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 39 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，天子飲酎，用禮樂」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，天子飲酎，用禮樂。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-40","chapterId":"li-ji_ch-6","order":40,"canonicalText":"孟夏行秋令，則苦雨數來，五穀不滋，四鄙入保。行冬令，則草木蚤枯，後乃大水，敗其城郭。行春令，則蝗蟲為災，暴風來格，秀草不實。","sentenceIds":["li-ji_ch-6_p-40_s-1","li-ji_ch-6_p-40_s-2","li-ji_ch-6_p-40_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲秋之月：日夜分，雷始收聲，蟄蟲坯戶；殺氣漸盛，乃命司寇修繕牢獄，理刑獄以順秋氣之肅殺。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 40 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「孟夏行秋令，則苦雨數來，五穀不滋，四鄙入保」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「孟夏行秋令，則苦雨數來，五穀不滋，四鄙入保。行冬令，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-41","chapterId":"li-ji_ch-6","order":41,"canonicalText":"仲夏之月，日在東井，昏亢中，旦危中。其日丙丁。其帝炎帝，其神祝融。其蟲羽。其音徵，律中蕤賓。其數七。其味苦，其臭焦。其祀竈，祭先肺。","sentenceIds":["li-ji_ch-6_p-41_s-1","li-ji_ch-6_p-41_s-2","li-ji_ch-6_p-41_s-3","li-ji_ch-6_p-41_s-4","li-ji_ch-6_p-41_s-5","li-ji_ch-6_p-41_s-6","li-ji_ch-6_p-41_s-7","li-ji_ch-6_p-41_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲夏的月，日在東井，昏亢中，旦危中。他的日丙丁。他的帝炎帝，他的神祝融。他的蟲羽。他的音徵，律中蕤賓。他的數七。他的味苦，他的臭焦。他的祀竈，祭先肺。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 41 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「仲夏之月，日在東井，昏亢中，旦危中」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「仲夏之月，日在東井，昏亢中，旦危中。其日丙丁。其帝炎……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-42","chapterId":"li-ji_ch-6","order":42,"canonicalText":"小暑至，螳蜋生。鵙始鳴，反舌無聲。","sentenceIds":["li-ji_ch-6_p-42_s-1","li-ji_ch-6_p-42_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲夏五月，小暑節氣來臨，螳螂感應微陰之氣破卵而生，伯勞鳥在枝頭發出清厲啼叫，善鳴的反舌鳥則停止歌唱陷入沉寂。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 42 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「小暑至，螳蜋生」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「小暑至，螳蜋生。鵙始鳴，反舌無聲。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-43","chapterId":"li-ji_ch-6","order":43,"canonicalText":"天子居明堂太廟，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤玉，食菽與雞，其器高以粗。養壯佼。","sentenceIds":["li-ji_ch-6_p-43_s-1","li-ji_ch-6_p-43_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲夏五月之時，天子居住在明堂南面的正堂「明堂太廟」之中。乘坐塗抹朱漆的朱路車駕，駕馭赤色黑鬣的赤騮良馬，車上插設赤色旗幟，身穿朱紅朝服，佩戴赤色美玉。進食大豆與雞肉，所用器具器形崇高質樸。朝廷在此盛陽之際優厚奉養精力充沛、勇力過人的壯健之士，以助養天地健壯之陽氣。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 43 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天子居明堂太廟，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤玉，食菽與雞，其器高以粗」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天子居明堂太廟，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-44","chapterId":"li-ji_ch-6","order":44,"canonicalText":"是月也，命樂師修鞀鞞鼓，均琴瑟管簫，執干戚戈羽，調竽笙篪簧，飭鐘磬柷敔。命有司為民祈祀山川百源，大雩帝，用盛樂。乃命百縣，雩祀百辟卿士有益於民者，以祈穀實。農乃登黍。","sentenceIds":["li-ji_ch-6_p-44_s-1","li-ji_ch-6_p-44_s-2","li-ji_ch-6_p-44_s-3","li-ji_ch-6_p-44_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，命雅樂和聲與心靈感化師修鞀鞞鼓，均琴瑟管簫，執干戚戈羽，調竽笙篪簧，飭鐘磬柷敔。命有司為民祈祀山川百源，大雩帝，用盛雅樂和聲與心靈感化。乃命百縣，雩祀百辟卿士人階層有益於民的人或禮儀規程與道崇高德行與品性修養規範制規範，以祈穀實。農乃登黍。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 44 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，命樂師修鞀鞞鼓，均琴瑟管簫，執干戚戈羽，調竽笙篪簧，飭鐘磬柷敔」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，命樂師修鞀鞞鼓，均琴瑟管簫，執干戚戈羽，調竽……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-45","chapterId":"li-ji_ch-6","order":45,"canonicalText":"是月也，天子乃以雛嘗黍，羞以含桃，先薦寢廟。令民毋艾藍以染，毋燒灰，毋暴布。門閭毋閉，關市毋索。挺重囚，益其食。遊牝別羣，則縶騰駒，班馬政。","sentenceIds":["li-ji_ch-6_p-45_s-1","li-ji_ch-6_p-45_s-2","li-ji_ch-6_p-45_s-3","li-ji_ch-6_p-45_s-4","li-ji_ch-6_p-45_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季秋之月：霜始降，草木黃落，百蟲咸俯；乃命農人登穀，天子行嘗祭以享先祖，收割完備而歲功告成。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 45 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，天子乃以雛嘗黍，羞以含桃，先薦寢廟」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，天子乃以雛嘗黍，羞以含桃，先薦寢廟。令民毋艾……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-46","chapterId":"li-ji_ch-6","order":46,"canonicalText":"是月也，日長至，陰陽爭，死生分。君子齊戒，處必掩身，毋躁。止聲色，毋或進。薄滋味，毋致和。節嗜慾，定心氣，百官靜事毋刑，以定晏陰之所成。鹿角解，蟬始鳴。半夏生，木堇榮。","sentenceIds":["li-ji_ch-6_p-46_s-1","li-ji_ch-6_p-46_s-2","li-ji_ch-6_p-46_s-3","li-ji_ch-6_p-46_s-4","li-ji_ch-6_p-46_s-5","li-ji_ch-6_p-46_s-6","li-ji_ch-6_p-46_s-7"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，日長至，陰陽爭，死生分。具有道德修養之君子賢士人階層齊戒，處必掩身，毋躁。止聲色，毋或進。薄滋味，毋致和。節嗜慾，定心氣，百官靜事毋刑，以定晏陰的所成。鹿角解，蟬始鳴。半夏生，木堇榮。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 46 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，日長至，陰陽爭，死生分」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，日長至，陰陽爭，死生分。君子齊戒，處必掩身，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-47","chapterId":"li-ji_ch-6","order":47,"canonicalText":"是月也，毋用火南方。可以居高明，可以遠眺望，可以升山陵，可以處臺榭。","sentenceIds":["li-ji_ch-6_p-47_s-1","li-ji_ch-6_p-47_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，因為南方正當火德盛極之位，嚴禁在南方任意用火點火燒荒。此時人們可以登上高峻明朗之處居住避暑，可以放眼極目遠眺，可以攀登高山崇陵以舒暢胸臆，可以休憩停留於通風涼爽的高台樓榭之上。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 47 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，毋用火南方」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，毋用火南方。可以居高明，可以遠眺望，可以升山……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-48","chapterId":"li-ji_ch-6","order":48,"canonicalText":"仲夏行冬令，則雹凍傷穀，道路不通，暴兵來至。行春令，則五穀晚熟，百螣時起，其國乃饑。行秋令，則草木零落，果實早成，民殃於疫。","sentenceIds":["li-ji_ch-6_p-48_s-1","li-ji_ch-6_p-48_s-2","li-ji_ch-6_p-48_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲夏五月若是推行了冬季的政令，就會降下酷烈冰雹凍害損害莊稼穀物，道路泥濘冰封難以通行，突發的暴亂兵災就會猝然襲來。若是推行了春季的政令，田間五穀就會生長遲緩過晚成熟，百種食葉害蟲隨時猖獗滋生，國家因此陷入嚴重大饑荒。若是推行了秋季的政令，草木便會提前枯黃凋落，各類瓜果被迫過早成熟而失其甜美，百姓亦深受各類流行疫病的大規模戕害。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 48 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「仲夏行冬令，則雹凍傷穀，道路不通，暴兵來至」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「仲夏行冬令，則雹凍傷穀，道路不通，暴兵來至。行春令，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-49","chapterId":"li-ji_ch-6","order":49,"canonicalText":"季夏之月，日在柳，昏火中，旦奎中。其日丙丁。其帝炎帝，其神祝融。其蟲羽。其音徵，律中林鐘。其數七。其味苦，其臭焦。其祀竈，祭先肺。","sentenceIds":["li-ji_ch-6_p-49_s-1","li-ji_ch-6_p-49_s-2","li-ji_ch-6_p-49_s-3","li-ji_ch-6_p-49_s-4","li-ji_ch-6_p-49_s-5","li-ji_ch-6_p-49_s-6","li-ji_ch-6_p-49_s-7","li-ji_ch-6_p-49_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季夏的月，日在柳，昏火中，旦奎中。他的日丙丁。他的帝炎帝，他的神祝融。他的蟲羽。他的音徵，律中林鐘。他的數七。他的味苦，他的臭焦。他的祀竈，祭先肺。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 49 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「季夏之月，日在柳，昏火中，旦奎中」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「季夏之月，日在柳，昏火中，旦奎中。其日丙丁。其帝炎帝……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-50","chapterId":"li-ji_ch-6","order":50,"canonicalText":"溫風始至，蟋蟀居壁，鷹乃學習，腐草為螢。","sentenceIds":["li-ji_ch-6_p-50_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟冬之月：水始冰，地始凍，雉入大水為蜃；天子迎冬於北郊，修嚴冬閉藏之備，命百官儲備薪柴以御嚴寒。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 50 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「溫風始至，蟋蟀居壁，鷹乃學習，腐草為螢」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「溫風始至，蟋蟀居壁，鷹乃學習，腐草為螢。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-51","chapterId":"li-ji_ch-6","order":51,"canonicalText":"天子居明堂右個，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤玉。食菽與雞，其器高以粗。命漁師伐蛟取鼉，登龜取黿。命澤人納材葦。","sentenceIds":["li-ji_ch-6_p-51_s-1","li-ji_ch-6_p-51_s-2","li-ji_ch-6_p-51_s-3","li-ji_ch-6_p-51_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季夏六月之時，天子居住在明堂西南側的「明堂右個」偏室之中。乘坐朱紅色朱路車駕，駕馭赤騮駿馬，載設赤色旗幟，身穿朱色朝服，佩戴赤玉。進食大豆與雞肉，所使用的各類器具器形高大粗質。命令掌管捕魚水產的「漁師」討伐捕殺兇惡的蛟龍並捕獲鼉龍，收取巨龜與大黿。命令掌管水澤的「澤人」採集進獻用於編織各類器物的蒲葦與蘆材。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 51 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天子居明堂右個，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤玉」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天子居明堂右個，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-52","chapterId":"li-ji_ch-6","order":52,"canonicalText":"是月也，命四監大合百縣之秩芻，以養犧牲。令民無不鹹出其力，以共皇天上帝名山大川四方之神，以祠宗廟社稷之靈，以為民祈福。","sentenceIds":["li-ji_ch-6_p-52_s-1","li-ji_ch-6_p-52_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，命四監大合百縣的秩芻，以養犧牲。令民無不鹹出他的力，以共皇天上帝名山大川四方的神，以祠宗廟社稷的靈，以為民祈福。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 52 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，命四監大合百縣之秩芻，以養犧牲」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，命四監大合百縣之秩芻，以養犧牲。令民無不鹹出……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-53","chapterId":"li-ji_ch-6","order":53,"canonicalText":"是月也，命婦官染採，黼黻文章，必以法故，無或差貸。黑黃倉赤，莫不質良，毋敢詐偽，以給郊廟祭祀之服，以為旗章，以別貴賤等給之度。","sentenceIds":["li-ji_ch-6_p-53_s-1","li-ji_ch-6_p-53_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，命婦官染採，黼黻文章，必以法所以，無或差貸。黑黃倉赤，莫不質良，毋敢詐偽，以給郊廟祭祀的服，以為旗章，以別貴賤等給的度。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 53 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，命婦官染採，黼黻文章，必以法故，無或差貸」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，命婦官染採，黼黻文章，必以法故，無或差貸。黑……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-54","chapterId":"li-ji_ch-6","order":54,"canonicalText":"是月也，樹木方盛，乃命虞人入山行木，毋有斬伐。不可以興土功，不可以合諸侯，不可以起兵動眾，毋舉大事，以搖養氣。毋發令而待，以妨神農之事也。水潦盛昌，神農將持功，舉大事則有天殃。","sentenceIds":["li-ji_ch-6_p-54_s-1","li-ji_ch-6_p-54_s-2","li-ji_ch-6_p-54_s-3","li-ji_ch-6_p-54_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，草木林木正當枝繁葉茂盛長之際，命令主管山林的虞人入山巡察林木，嚴禁任何人隨意砍伐樹木。此時不可興辦各類土木營造工程，不可合會召集四方諸侯，不可輕易起兵動眾行軍打仗，切切不可興辦一切勞民傷財的重大政事，以免劇烈震動消耗天地長養萬物的溫潤陽氣。不可隨意發布徭役號令讓百姓待命，以免妨礙妨誤炎帝神農所主掌的農耕盛事。此時正當水潦陰雨豐沛昌盛之候，神農農神正要保全成全大地農功，若在此時輕舉妄動大興兵戈徭役，必將招致上天降下的災殃懲罰。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 54 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，樹木方盛，乃命虞人入山行木，毋有斬伐」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，樹木方盛，乃命虞人入山行木，毋有斬伐。不可以……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-55","chapterId":"li-ji_ch-6","order":55,"canonicalText":"是月也，土潤溽暑，大雨時行，燒薙行水，利以殺草，如以熱湯。可以糞田疇，可以美土強。","sentenceIds":["li-ji_ch-6_p-55_s-1","li-ji_ch-6_p-55_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲冬之月：日短至，陰陽交泰，萬物潛藏；命山林水澤閉封，禁止採捕，養護地氣以待來年陽春。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 55 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，土潤溽暑，大雨時行，燒薙行水，利以殺草，如以熱湯」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，土潤溽暑，大雨時行，燒薙行水，利以殺草，如以……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-56","chapterId":"li-ji_ch-6","order":56,"canonicalText":"季夏行春令，則穀實鮮落，國多風咳，民乃遷徙。行秋令，則丘隰水潦，禾稼不熟，乃多女災。行冬令，則風寒不時，鷹隼蚤鷙，四鄙入保。","sentenceIds":["li-ji_ch-6_p-56_s-1","li-ji_ch-6_p-56_s-2","li-ji_ch-6_p-56_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季夏六月若是推行了春季的政令，田間五穀結出的穀粒就會乾枯稀少脫落，國家境內多流行傷風感冒、咳嗽氣喘之疾，百姓難以忍受而不得不舉家逃荒遷徙。若是推行了秋季的政令，丘陵低窪之地就會暴發嚴重山洪內澇，禾稼莊稼無法成熟，民間多發婦女流產難產之災。若是推行了冬季的政令，陰寒冷風便會非時吹襲，鷹隼等猛禽提早兇猛搏擊獵食，四方邊鄙的百姓被迫躲入堡壘之中以禦寒冬與盜寇。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 56 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「季夏行春令，則穀實鮮落，國多風咳，民乃遷徙」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「季夏行春令，則穀實鮮落，國多風咳，民乃遷徙。行秋令，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-57","chapterId":"li-ji_ch-6","order":57,"canonicalText":"中央土。其日戊己。其帝黃帝，其神后土。其蟲裸，其音宮，律中黃鐘之宮。其數五。其味甘，其臭香。其祠中溜，祭先心。","sentenceIds":["li-ji_ch-6_p-57_s-1","li-ji_ch-6_p-57_s-2","li-ji_ch-6_p-57_s-3","li-ji_ch-6_p-57_s-4","li-ji_ch-6_p-57_s-5","li-ji_ch-6_p-57_s-6","li-ji_ch-6_p-57_s-7"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"中央土。他的日戊己。他的帝黃帝，他的神后土。他的蟲裸，他的音宮，律中黃鐘的宮。他的數五。他的味甘，他的臭香。他的祠中溜，祭先心。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 57 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「中央土」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「中央土。其日戊己。其帝黃帝，其神后土。其蟲裸，其音宮……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-58","chapterId":"li-ji_ch-6","order":58,"canonicalText":"天子居大廟大室，乘大路，駕黃騮，載黃旗，衣黃衣，服黃玉，食稷與牛，其器圜以閎。","sentenceIds":["li-ji_ch-6_p-58_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在季夏與孟秋之間的中央土德寄治之期，天子移居於明堂正中央的「大廟大室」（太室中心殿堂）。乘坐莊嚴厚重的黃色「大路」玉輅車駕，駕馭赤身黑鬣的黃騮黃馬，車上載設繪有日月圖紋的黃色龍旗，身穿象徵中土之德的黃色禮服，佩戴潤澤的黃玉。進食代表土地精華的稷米（黃米）與牛肉，所使用的各類器具器形圓融渾厚而內部宏闊寬大，以順應中央坤土含弘光大、包容生養萬物之德。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 58 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天子居大廟大室，乘大路，駕黃騮，載黃旗，衣黃衣，服黃玉，食稷與牛，其器圜以閎」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天子居大廟大室，乘大路，駕黃騮，載黃旗，衣黃衣，服黃……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-59","chapterId":"li-ji_ch-6","order":59,"canonicalText":"孟秋之月，日在翼，昏建星中，旦畢中。其日庚辛。其帝少皞，其神蓐收。其蟲毛。其音商，律中夷則。其數九。其味辛，其臭腥。其祀門，祭先肝。","sentenceIds":["li-ji_ch-6_p-59_s-1","li-ji_ch-6_p-59_s-2","li-ji_ch-6_p-59_s-3","li-ji_ch-6_p-59_s-4","li-ji_ch-6_p-59_s-5","li-ji_ch-6_p-59_s-6","li-ji_ch-6_p-59_s-7","li-ji_ch-6_p-59_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟秋的月，日在翼，昏建星中，旦畢中。他的日庚辛。他的帝少皞，他的神蓐收。他的蟲毛。他的音商，律中夷則。他的數九。他的味辛，他的臭腥。他的祀門，祭先肝。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 59 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「孟秋之月，日在翼，昏建星中，旦畢中」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「孟秋之月，日在翼，昏建星中，旦畢中。其日庚辛。其帝少……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-60","chapterId":"li-ji_ch-6","order":60,"canonicalText":"涼風至，白露降，寒蟬鳴。鷹乃祭鳥，用始行戮。","sentenceIds":["li-ji_ch-6_p-60_s-1","li-ji_ch-6_p-60_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季冬之月：歲月將暮，日窮於次，月窮於紀，星回於天；行大儺之禮以逐百鬼疫病，天子出土牛以送寒氣，準備迎新春之復始也。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 60 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「涼風至，白露降，寒蟬鳴」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「涼風至，白露降，寒蟬鳴。鷹乃祭鳥，用始行戮。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-61","chapterId":"li-ji_ch-6","order":61,"canonicalText":"天子居總章左個，乘戎路，駕白駱，載白旗，衣白衣，服白玉，食麻與犬，其器廉以深。","sentenceIds":["li-ji_ch-6_p-61_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟秋七月之時，天子居住在明堂西面的「總章左個」（西南偏室）。乘坐塗抹白漆、利於軍事的白色「戎路」戰車，駕馭純白黑鬣的白駱良馬，車上載設純白旗幟，身穿素白禮服，佩戴潤澤白玉。進食大麻籽米與犬肉，所使用的各類器具器身廉棱鋒利而器腹深沉收斂，以順應秋季金氣肅殺凝重之象。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 61 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天子居總章左個，乘戎路，駕白駱，載白旗，衣白衣，服白玉，食麻與犬，其器廉以深」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天子居總章左個，乘戎路，駕白駱，載白旗，衣白衣，服白……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-62","chapterId":"li-ji_ch-6","order":62,"canonicalText":"是月也，以立秋。先立秋三日，大史謁之天子曰：某日立秋，盛德在金。天子乃齊。立秋之日，天子親帥三公、九卿、諸侯、大夫，以迎秋於西郊。還反，賞軍帥武人於朝。天子乃命將帥，選士厲兵，簡練桀俊，專任有功，以徵不義。詰誅暴慢，以明好惡，順彼遠方。","sentenceIds":["li-ji_ch-6_p-62_s-1","li-ji_ch-6_p-62_s-2","li-ji_ch-6_p-62_s-3","li-ji_ch-6_p-62_s-4","li-ji_ch-6_p-62_s-5","li-ji_ch-6_p-62_s-6","li-ji_ch-6_p-62_s-7"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，以立秋。先立秋三日，大史謁的天孔子先生親自開示教導說道：某日立秋，盛崇高德行與品性修養在金。天子乃齊。立秋的日，天子親帥三公、九卿、諸侯、卿大夫貴族官員，以迎秋於西郊。還反，賞軍帥武人於朝。天子乃命將帥，選士人階層厲兵，簡練桀俊，專任有功，以徵不正義公道之道義。詰誅暴慢，以明好惡，順彼遠方。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 62 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，以立秋」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，以立秋。先立秋三日，大史謁之天子曰：某日立秋……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-63","chapterId":"li-ji_ch-6","order":63,"canonicalText":"是月也，命有司修法制，繕囹圄，具桎梏，禁止奸，慎罪邪，務搏執。命理瞻傷，察創，視折，審斷。決獄訟，必端平。戮有罪，嚴斷刑。天地始肅，不可以贏。","sentenceIds":["li-ji_ch-6_p-63_s-1","li-ji_ch-6_p-63_s-2","li-ji_ch-6_p-63_s-3","li-ji_ch-6_p-63_s-4","li-ji_ch-6_p-63_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，命令主管法制的官員修明法令法制，修繕加固監獄牢房，備齊木枷腳鐐等各類桎梏刑具，嚴厲禁止一切奸詐非違之行，審慎懲處各類邪惡犯罪，全力緝拿捕獲盜賊兇犯。命令法官掌囚「理官」詳察傷勢、檢驗創口、辨明骨折受損程度，審慎公平作出刑獄判斷。裁決爭訟獄案時務必端正平允公道。誅殺處決罪大惡極的有罪之徒，嚴厲果斷施行肉刑刑罰。此時天地肅殺之氣剛剛興起，用刑必須嚴明有度，切不可任性寬縱或過分盈濫。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 63 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，命有司修法制，繕囹圄，具桎梏，禁止奸，慎罪邪，務搏執」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，命有司修法制，繕囹圄，具桎梏，禁止奸，慎罪邪……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-64","chapterId":"li-ji_ch-6","order":64,"canonicalText":"是月也，農乃登穀。天子嘗新，先薦寢廟。命百官，始收斂。完堤防，謹壅塞，以備水潦。修宮室，壞墻垣，補城郭。","sentenceIds":["li-ji_ch-6_p-64_s-1","li-ji_ch-6_p-64_s-2","li-ji_ch-6_p-64_s-3","li-ji_ch-6_p-64_s-4","li-ji_ch-6_p-64_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，農民秋收的各類穀物開始收割登場。天子主持嘗新典禮品嚐新熟五穀，首先將新穀進獻於先祖寢廟。命令朝廷百官，正式開始全面督導秋收收斂入庫之事。加固修繕江河堤壩，審慎防堵一切破口壅塞，以防秋季山洪澇水氾濫。修繕保養宮殿居室，拆除傾頹殘破的土牆矮垣，補綴修固城防郭牆以備冬藏。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 64 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，農乃登穀」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，農乃登穀。天子嘗新，先薦寢廟。命百官，始收斂……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-65","chapterId":"li-ji_ch-6","order":65,"canonicalText":"是月也，毋以封諸侯、立大官。毋以割地、行大使、出大幣。","sentenceIds":["li-ji_ch-6_p-65_s-1","li-ji_ch-6_p-65_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，因為天地肅殺斂藏之氣漸盛，朝廷不得在此時舉行分封諸侯、冊立三公九卿大官的盛典。不得以此時舉行割讓國土土地、派遣持節特使、以及頒發大規模賞賜巨額幣帛的政事。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 65 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，毋以封諸侯、立大官」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，毋以封諸侯、立大官。毋以割地、行大使、出大幣。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-66","chapterId":"li-ji_ch-6","order":66,"canonicalText":"孟秋行冬令，則陰氣大勝，介蟲敗穀，戎兵乃來。行春令，則其國乃旱，陽氣復還，五穀無實。行夏令，則國多火災，寒熱不節，民多瘧疾。","sentenceIds":["li-ji_ch-6_p-66_s-1","li-ji_ch-6_p-66_s-2","li-ji_ch-6_p-66_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟秋七月若是推行了冬季的政令，肅殺陰氣就會過早大勝盛行，甲殼類害蟲就會繁盛成災毀敗穀物，外敵戎狄軍隊就會趁機大舉來犯。若是推行了春季的政令，國家境內就會發生嚴重乾旱，春季發散的陽氣重新反撲，導致秋田五穀空癟無實顆粒無收。若是推行了夏季的政令，國家多發火災火患，氣候寒熱交替失節無常，民間多流行瘧疾發冷發熱之疾。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 66 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「孟秋行冬令，則陰氣大勝，介蟲敗穀，戎兵乃來」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「孟秋行冬令，則陰氣大勝，介蟲敗穀，戎兵乃來。行春令，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-67","chapterId":"li-ji_ch-6","order":67,"canonicalText":"仲秋之月，日在角，昏牽牛中，旦觜觿中。其日庚辛，其帝少皞，其神蓐收。其蟲毛。其音商，律中南呂。其數九。其味辛，其臭腥。其祀門，祭先肝。","sentenceIds":["li-ji_ch-6_p-67_s-1","li-ji_ch-6_p-67_s-2","li-ji_ch-6_p-67_s-3","li-ji_ch-6_p-67_s-4","li-ji_ch-6_p-67_s-5","li-ji_ch-6_p-67_s-6","li-ji_ch-6_p-67_s-7"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲秋的月，日在角，昏牽牛中，旦觜觿中。他的日庚辛，他的帝少皞，他的神蓐收。他的蟲毛。他的音商，律中南呂。他的數九。他的味辛，他的臭腥。他的祀門，祭先肝。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 67 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「仲秋之月，日在角，昏牽牛中，旦觜觿中」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「仲秋之月，日在角，昏牽牛中，旦觜觿中。其日庚辛，其帝……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-68","chapterId":"li-ji_ch-6","order":68,"canonicalText":"盲風至，鴻雁來，玄鳥歸，羣鳥養羞。","sentenceIds":["li-ji_ch-6_p-68_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲秋八月，疾勁的暴風狂飆而至，北方的大雁成群南飛而來，春來繁殖的燕子整隊南歸，百鳥紛紛貯藏儲備過冬食物。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 68 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「盲風至，鴻雁來，玄鳥歸，羣鳥養羞」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「盲風至，鴻雁來，玄鳥歸，羣鳥養羞。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-69","chapterId":"li-ji_ch-6","order":69,"canonicalText":"天子居總章大廟，乘戎路，駕白駱，載白旗，衣白衣，服白玉，食麻與犬，其器廉以深。","sentenceIds":["li-ji_ch-6_p-69_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲秋八月之時，天子居住在明堂西側正堂「總章大廟」之中。乘坐白色戎路車駕，駕馭純白白駱良馬，載設白旗，身穿純白朝服，佩戴純白美玉。進食麻籽飯與犬肉，所用器具皆稜角方正廉折而器腹深邃。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 69 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天子居總章大廟，乘戎路，駕白駱，載白旗，衣白衣，服白玉，食麻與犬，其器廉以深」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天子居總章大廟，乘戎路，駕白駱，載白旗，衣白衣，服白……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-70","chapterId":"li-ji_ch-6","order":70,"canonicalText":"是月也，養衰老，授几杖，行糜粥飲食。乃命司服，具飭衣裳，文繡有恆，制有小大，度有長短。衣服有量，必循其故，冠帶有常。乃命有司，申嚴百刑，斬殺必當，毋或枉橈。枉橈不當，反受其殃。","sentenceIds":["li-ji_ch-6_p-70_s-1","li-ji_ch-6_p-70_s-2","li-ji_ch-6_p-70_s-3","li-ji_ch-6_p-70_s-4","li-ji_ch-6_p-70_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，朝廷舉行優禮養老之禮奉養衰老老者，頒賜安居養老的几案與手杖，向老人賞賜供應細膩溫軟的糜粥膳食。隨後命令掌管服裝的「司服」官員，備辦整飭秋冬祭祀與朝會衣裳，刺繡花紋要有法定恆常制度，剪裁規格要辨明大中小號，量度長短尺寸各有法制。衣裳裁製要符合等級限度，必須恪守古來常軌，冠冕帶飾各有規律不可紊亂。隨後命令司法官吏，重新申明嚴肅各類刑律條款，凡涉及斬首處決的重刑必須裁量精當罪刑相稱，切切不可有絲毫枉法屈曲情弊。若有枉法屈情或判罰不當，審判官員必將反受國法嚴厲嚴懲。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 70 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，養衰老，授几杖，行糜粥飲食」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，養衰老，授几杖，行糜粥飲食。乃命司服，具飭衣……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-71","chapterId":"li-ji_ch-6","order":71,"canonicalText":"是月也，乃命宰祝，循行犧牲，視全具，案芻豢，瞻肥瘠，察物色。必比類，量小大，視長短，皆中度。五者備當，上帝其饗。天子乃難，以達秋氣。以犬嘗麻，先薦寢廟。","sentenceIds":["li-ji_ch-6_p-71_s-1","li-ji_ch-6_p-71_s-2","li-ji_ch-6_p-71_s-3","li-ji_ch-6_p-71_s-4","li-ji_ch-6_p-71_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，乃命宰祝，循行犧牲，視全具，案芻豢，瞻肥瘠，察物色。必比類，量小大，視長短，皆中度。五的人或禮儀規程與道崇高德行與品性修養規範制規範備當，上帝他的饗。天子乃難，以達秋氣。以犬嘗麻，先薦寢廟。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 71 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，乃命宰祝，循行犧牲，視全具，案芻豢，瞻肥瘠，察物色」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，乃命宰祝，循行犧牲，視全具，案芻豢，瞻肥瘠，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-72","chapterId":"li-ji_ch-6","order":72,"canonicalText":"是月也，可以築城郭，建都邑，穿竇窖，修囷倉。乃命有司，趣民收斂，務畜菜，多積聚。乃勸種麥，毋或失時。其有失時，行罪無疑。","sentenceIds":["li-ji_ch-6_p-72_s-1","li-ji_ch-6_p-72_s-2","li-ji_ch-6_p-72_s-3","li-ji_ch-6_p-72_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，秋高氣爽土性堅實，可以正式組織興築城牆郭郭，修建城邑聚落，挖掘深邃的地下地窖冰窖，修葺露天糧囤與室內糧倉。於是命令有司官員，嚴格督促農民加緊收割儲藏莊稼，務必大量醃製儲存各類蔬菜乾菜，廣泛積聚各類過冬物資。隨後勉勵勸導農民加緊播種冬麥，切切不可耽擱延誤播種農時。對於違背怠慢農時者，必將依律科處刑罪懲處不貸。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 72 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，可以築城郭，建都邑，穿竇窖，修囷倉」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，可以築城郭，建都邑，穿竇窖，修囷倉。乃命有司……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-73","chapterId":"li-ji_ch-6","order":73,"canonicalText":"是月也，日夜分，雷始收聲。蟄蟲壞戶，殺氣浸盛，陽氣日衰，水始涸。日夜分，則同度量，平權衡，正鈞石，角鬥甬。","sentenceIds":["li-ji_ch-6_p-73_s-1","li-ji_ch-6_p-73_s-2","li-ji_ch-6_p-73_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，秋分節氣到來，晝夜長短均分，天空中的雷聲開始收斂止息。蟄居地下的各類昆蟲開始用泥土封堵洞口以備冬眠，天地肅殺之氣逐漸鼎盛，陽氣日益衰微內收，江河水澤之水開始乾涸退落。晝夜均分之際，官府全面統一天下的度量衡標準：校準長短尺度，校平衡量輕重的秤桿權衡，校準三十斤的「鈞」與一百二十斤的「石」，核驗校準盛裝容量的「斗」與十六斗的「甬」，確保全國度量公允平正。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 73 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，日夜分，雷始收聲」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，日夜分，雷始收聲。蟄蟲壞戶，殺氣浸盛，陽氣日……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-74","chapterId":"li-ji_ch-6","order":74,"canonicalText":"是月也，易關市，來商旅，納貨賄，以便民事。四方來集，遠鄉皆至，則財不匱，上無乏用，百事乃遂。凡舉大事，毋逆大數，必順其時，慎因其類。","sentenceIds":["li-ji_ch-6_p-74_s-1","li-ji_ch-6_p-74_s-2","li-ji_ch-6_p-74_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，放寬邊境關卡與市集的商貿稅收與關禁，招徠各地商賈旅客前來貿易，納入天下各類貨物財利，以方便百姓日用民事。四方商旅紛紛匯聚，遠鄉賓客紛紛前來，如此則國家財物豐裕不致匱乏，朝廷公用無所短缺，各項國政事務皆得順遂亨通。凡是興辦國家大事，切不可違背天地陰陽的根本大數，必須順應四時天道運行規律，謹慎依照萬物類別因勢利導。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 74 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，易關市，來商旅，納貨賄，以便民事」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，易關市，來商旅，納貨賄，以便民事。四方來集，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-75","chapterId":"li-ji_ch-6","order":75,"canonicalText":"仲秋行春令，則秋雨不降，草木生榮，國乃有恐。行夏令，則其國乃旱，蟄蟲不藏，五穀復生。行冬令，則風災數起，收雷先行，草木蚤死。","sentenceIds":["li-ji_ch-6_p-75_s-1","li-ji_ch-6_p-75_s-2","li-ji_ch-6_p-75_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲秋八月若是推行了春季的政令，秋雨就會遲遲不降造成乾旱，草木重新萌發開花茂盛，國家境內人心惶惶常常生出驚恐之事。若是推行了夏季的政令，國家境內就會遭受大旱，本當冬眠的蟄蟲不肯入土潛藏，田間成熟落地的五穀甚至再度發芽重生。若是推行了冬季的政令，大風風災頻頻暴作，肅殺寒雷提早響起，秋季草木過早凋零凍死。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 75 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「仲秋行春令，則秋雨不降，草木生榮，國乃有恐」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「仲秋行春令，則秋雨不降，草木生榮，國乃有恐。行夏令，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-76","chapterId":"li-ji_ch-6","order":76,"canonicalText":"季秋之月，日在房，昏虛中，旦柳中。其日庚辛。其帝少皞，其神蓐收。其蟲毛。其音商，律中無射。其數九。其味辛，其臭腥。其祀門，祭先肝。","sentenceIds":["li-ji_ch-6_p-76_s-1","li-ji_ch-6_p-76_s-2","li-ji_ch-6_p-76_s-3","li-ji_ch-6_p-76_s-4","li-ji_ch-6_p-76_s-5","li-ji_ch-6_p-76_s-6","li-ji_ch-6_p-76_s-7","li-ji_ch-6_p-76_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季秋的月，日在房，昏虛中，旦柳中。他的日庚辛。他的帝少皞，他的神蓐收。他的蟲毛。他的音商，律中無射。他的數九。他的味辛，他的臭腥。他的祀門，祭先肝。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 76 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「季秋之月，日在房，昏虛中，旦柳中」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「季秋之月，日在房，昏虛中，旦柳中。其日庚辛。其帝少皞……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-77","chapterId":"li-ji_ch-6","order":77,"canonicalText":"鴻雁來賓，爵入大水為蛤。鞠有黃華，豺乃祭獸戮禽。","sentenceIds":["li-ji_ch-6_p-77_s-1","li-ji_ch-6_p-77_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季秋九月，最後一批大雁遠道而來宛如過客寄宿，雀鳥潛入大澤化為海蛤。野菊迎霜綻放出金黃花朵，豺狼獵殺禽獸陳列四方如同享祭。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 77 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「鴻雁來賓，爵入大水為蛤」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「鴻雁來賓，爵入大水為蛤。鞠有黃華，豺乃祭獸戮禽。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-78","chapterId":"li-ji_ch-6","order":78,"canonicalText":"天子居總章右個，乘戎路，駕白駱，載白旗，衣白衣，服白玉。食麻與犬，其器廉以深。","sentenceIds":["li-ji_ch-6_p-78_s-1","li-ji_ch-6_p-78_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季秋九月之時，天子居住在明堂西北側的「總章右個」偏室之中。乘坐白色戎路車駕，駕馭純白黑鬣白駱良馬，車上載設白旗，身穿白衣，佩戴白玉。進食麻籽飯與犬肉，所使用的各類器具器身廉棱深沉。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 78 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天子居總章右個，乘戎路，駕白駱，載白旗，衣白衣，服白玉」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天子居總章右個，乘戎路，駕白駱，載白旗，衣白衣，服白……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-79","chapterId":"li-ji_ch-6","order":79,"canonicalText":"是月也，申嚴號令。命百官貴賤無不務內，以會天地之藏，無有宣出。乃命冢宰，農事備收，舉五穀之要，藏帝藉之收於神倉，祗敬必飭。","sentenceIds":["li-ji_ch-6_p-79_s-1","li-ji_ch-6_p-79_s-2","li-ji_ch-6_p-79_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，申嚴號令。命百官貴賤無不務內，以會天地的藏，無有宣出。乃命冢宰，農事備收，舉五穀的要，藏帝藉的收於神倉，祗敬必飭。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 79 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，申嚴號令」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，申嚴號令。命百官貴賤無不務內，以會天地之藏，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-80","chapterId":"li-ji_ch-6","order":80,"canonicalText":"是月也，霜始降，則百工休。乃命有司曰：寒氣總至，民力不堪，其皆入室。上丁，命樂正入學習吹。","sentenceIds":["li-ji_ch-6_p-80_s-1","li-ji_ch-6_p-80_s-2","li-ji_ch-6_p-80_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，霜始降，則百工休。乃命有司說道：寒氣總至，民力不堪，他的皆入室。上丁，命雅樂和聲與心靈感化正入學習吹。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 80 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，霜始降，則百工休」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，霜始降，則百工休。乃命有司曰：寒氣總至，民力……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-81","chapterId":"li-ji_ch-6","order":81,"canonicalText":"是月也，大饗帝、嘗，犧牲告備於天子。合諸侯，制百縣，為來歲受朔日，與諸侯所稅於民輕重之法，貢職之數，以遠近土地所宜為度，以給郊廟之事，無有所私。","sentenceIds":["li-ji_ch-6_p-81_s-1","li-ji_ch-6_p-81_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，朝廷舉行盛大的「大饗帝」祭天盛典，並在宗廟舉行秋嘗祭祖之禮，掌牲之官將備辦齊全的各類純色牲牲畜呈告天子審察。天子大合天下諸侯，規範治理百縣政事，向各國頒布來年正朔曆書與頒曆之日，核定諸侯向民間百姓徵收田稅的輕重法度，審定各國向天子進貢任職貢賦的法定數額，依據各地疆域遠近與土地水土特產物宜為衡量標準，以充足供給祭祀天地郊廟神靈的神聖用度，在制度規程中不允許有任何私心偏袒。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 81 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，大饗帝、嘗，犧牲告備於天子」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，大饗帝、嘗，犧牲告備於天子。合諸侯，制百縣，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-82","chapterId":"li-ji_ch-6","order":82,"canonicalText":"是月也，天子乃教於田獵，以習五戎，班馬政。命僕及七騶鹹駕，載旌旐，授車以級，整設於屏外。司徒搢撲，北面誓之。天子乃厲飾，執弓挾矢以獵，命主祠祭禽於四方。","sentenceIds":["li-ji_ch-6_p-82_s-1","li-ji_ch-6_p-82_s-2","li-ji_ch-6_p-82_s-3","li-ji_ch-6_p-82_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，天子親自舉行秋季大搜田獵以演練教導軍陣，藉此操習車戰、步戰、弓矢、戈矛、甲冑等「五戎」武備戰陣技能，並全面頒布整飭馬政軍令。命令天子太僕御者及掌管宮廷馬匹的「七騶」之官全部套駕車馬，車上載設彩繪鳥隼與龜蛇圖案的旌旐旗幟，依照品級爵位高下分授戰車乘輿，將各路車隊齊整陳設於軍門外屏障之外。大司徒身插教刑刑杖木檟，面向北向全軍將士宣讀嚴肅誓詞。天子隨後身穿威嚴整肅的戎裝甲冑，親自挽持雕弓、挾夾利箭親行射獵，並命掌祭之官在四方郊野宰割獵獲的禽獸舉行祭祀四方之神的典禮。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 82 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，天子乃教於田獵，以習五戎，班馬政」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，天子乃教於田獵，以習五戎，班馬政。命僕及七騶……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-83","chapterId":"li-ji_ch-6","order":83,"canonicalText":"是月也，草木黃落，乃伐薪為炭。蟄蟲鹹俯在內，皆墐其戶。乃趣獄刑，毋留有罪。收祿秩之不當、供養之不宜者。","sentenceIds":["li-ji_ch-6_p-83_s-1","li-ji_ch-6_p-83_s-2","li-ji_ch-6_p-83_s-3","li-ji_ch-6_p-83_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，草木黃落，乃伐薪為炭。蟄蟲鹹俯在內，皆墐他的戶。乃趣獄刑，毋留有罪。收祿秩的不當、供養的不宜的人或禮儀規程與道崇高德行與品性修養規範制規範。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 83 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，草木黃落，乃伐薪為炭」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，草木黃落，乃伐薪為炭。蟄蟲鹹俯在內，皆墐其戶……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-84","chapterId":"li-ji_ch-6","order":84,"canonicalText":"是月也，天子乃以犬嘗稻，先薦寢廟。","sentenceIds":["li-ji_ch-6_p-84_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，天子乃以犬嘗稻，先薦寢廟。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 84 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，天子乃以犬嘗稻，先薦寢廟」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，天子乃以犬嘗稻，先薦寢廟。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-85","chapterId":"li-ji_ch-6","order":85,"canonicalText":"季秋行夏令，則其國大水，冬藏殃敗，民多鼽嚏。行冬令，則國多盜賊，邊境不寧，土地分裂。行春令，則暖風來至，民氣解惰，師興不居。","sentenceIds":["li-ji_ch-6_p-85_s-1","li-ji_ch-6_p-85_s-2","li-ji_ch-6_p-85_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季秋九月若是推行了夏季的政令，其國家便會暴發滔天大水洪澇，百姓冬藏儲備的糧食糧草全部受潮腐敗黴爛，民眾多罹患鼻塞流涕咳嗽之疾。若是推行了冬季的政令，國家境內就會盜賊橫行盜寇蜂起，邊境邊疆動盪不安不得安寧，甚至招致國土淪喪割裂分裂。若是推行了春季的政令，反常暖風便會拂逆吹來，民眾心氣鬆懈怠惰無力，軍隊出征頻繁疲憊不堪而無法安居衛國。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 85 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「季秋行夏令，則其國大水，冬藏殃敗，民多鼽嚏」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「季秋行夏令，則其國大水，冬藏殃敗，民多鼽嚏。行冬令，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-86","chapterId":"li-ji_ch-6","order":86,"canonicalText":"孟冬之月，日在尾，昏危中，旦七星中。其日壬癸。其帝顓頊，其神玄冥。其蟲介。其音羽，律中應鐘。其數六。其味鹹，其臭朽。其祀行，祭先腎。","sentenceIds":["li-ji_ch-6_p-86_s-1","li-ji_ch-6_p-86_s-2","li-ji_ch-6_p-86_s-3","li-ji_ch-6_p-86_s-4","li-ji_ch-6_p-86_s-5","li-ji_ch-6_p-86_s-6","li-ji_ch-6_p-86_s-7","li-ji_ch-6_p-86_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟冬的月，日在尾，昏危中，旦七星中。他的日壬癸。他的帝顓頊，他的神玄冥。他的蟲介。他的音羽，律中應鐘。他的數六。他的味鹹，他的臭朽。他的祀行，祭先腎。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 86 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「孟冬之月，日在尾，昏危中，旦七星中」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「孟冬之月，日在尾，昏危中，旦七星中。其日壬癸。其帝顓……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-87","chapterId":"li-ji_ch-6","order":87,"canonicalText":"水始冰，地始凍。雉入大水為蜃。虹藏不見。","sentenceIds":["li-ji_ch-6_p-87_s-1","li-ji_ch-6_p-87_s-2","li-ji_ch-6_p-87_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟冬十月，水面開始凝結薄冰，大地原野開始凍結變硬。野雉潛入江海大水化為大蛤蚌。天際彩虹隱匿不再出現。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 87 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「水始冰，地始凍」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「水始冰，地始凍。雉入大水為蜃。虹藏不見。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-88","chapterId":"li-ji_ch-6","order":88,"canonicalText":"天子居玄堂左個，乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄玉，食黍與彘，其器閎以奄。","sentenceIds":["li-ji_ch-6_p-88_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟冬十月之時，天子居住在明堂北側的「玄堂左個」（西北偏室）。乘坐塗抹純黑清漆的「玄路」車駕，駕馭純黑色的鐵驪駿馬，車上載設純黑玄旗，身穿黑色深衣禮服，佩戴深邃玄玉。進食黍米黃米與豬肉，所使用的各類器具器腹寬宏宏大而口部嚴密封閉，以順應冬季天地萬物深閉固藏之氣象。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 88 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天子居玄堂左個，乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄玉，食黍與彘，其器閎以奄」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天子居玄堂左個，乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-89","chapterId":"li-ji_ch-6","order":89,"canonicalText":"是月也，以立冬。先立冬三日，太史謁之天子曰：某日立冬，盛德在水。天子乃齊。立冬之日，天子親帥三公、九卿、大夫以迎冬於北郊，還反，賞死事，恤孤寡。","sentenceIds":["li-ji_ch-6_p-89_s-1","li-ji_ch-6_p-89_s-2","li-ji_ch-6_p-89_s-3","li-ji_ch-6_p-89_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，以立冬。先立冬三日，太史謁的天孔子先生親自開示教導說道：某日立冬，盛崇高德行與品性修養在水。天子乃齊。立冬的日，天子親帥三公、九卿、卿大夫貴族官員以迎冬於北郊，還反，賞死事，恤孤寡。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 89 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，以立冬」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，以立冬。先立冬三日，太史謁之天子曰：某日立冬……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-90","chapterId":"li-ji_ch-6","order":90,"canonicalText":"是月也，命大史釁龜策，佔兆審卦吉凶，是察阿黨，則罪無有掩蔽。","sentenceIds":["li-ji_ch-6_p-90_s-1"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，天子命令大史占卜之官宰殺牲畜取血塗抹於神龜與蓍草筮策以行「釁禮」，鑽龜占卜灼烤兆紋，審察周易卦象以定國家吉凶之數；並依此明察考察群臣是否有結黨營私、阿諛朋黨之奸惡行徑，使朝野間的一切隱秘罪愆無所掩蔽遁形。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 90 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，命大史釁龜策，佔兆審卦吉凶，是察阿黨，則罪無有掩蔽」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，命大史釁龜策，佔兆審卦吉凶，是察阿黨，則罪無……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-91","chapterId":"li-ji_ch-6","order":91,"canonicalText":"是月也，天子始裘。命有司曰：天氣上騰，地氣下降，天地不通，閉塞而成冬。命百官謹蓋藏。命司徒循行積聚，無有不斂。壞城郭，戒門閭，修鍵閉，慎管龠，固封疆，備邊竟，完要塞，謹關梁，塞徯徑。飭喪紀，辨衣裳，審棺槨之厚薄，塋丘壟之大小、高卑、厚薄之度，貴賤之等級。","sentenceIds":["li-ji_ch-6_p-91_s-1","li-ji_ch-6_p-91_s-2","li-ji_ch-6_p-91_s-3","li-ji_ch-6_p-91_s-4","li-ji_ch-6_p-91_s-5","li-ji_ch-6_p-91_s-6"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，天氣嚴寒，天子開始換穿厚重禦寒的皮裘。隨後告誡命令有司官員說：如今大地陰氣自下向上閉合，上天陽氣自上騰躍遠離，天地二氣陰陽不通隔絕，自然萬物徹底閉塞而進入寒冬。命令文武百官審慎封閉儲備各類庫藏物資。命令大司徒巡行各方查驗田野民間積蓄聚積，務必使所有收成收斂入庫無一遺漏在外。修繕防固城郭防務，警備檢查門閭戶籍，修治栓鎖鍵閉，慎重看守門鑰鑰匙，加固邊境封疆藩籬，整飭防備邊疆要隘，完善各處軍事堡壘，嚴密把守要塞關卡與津梁橋樑，封堵截斷各類山野私自偷越的便道小徑。全面整飭送終喪紀之禮，辨別各等衰麻喪服的吉凶規度，審定棺材與外槨的厚薄尺寸，劃定墳塋丘壟的佔地大小、封土高下與築土厚薄的度數標準，使一切制度悉數嚴格符合尊卑貴賤的等級法則。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 91 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，天子始裘」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，天子始裘。命有司曰：天氣上騰，地氣下降，天地……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-92","chapterId":"li-ji_ch-6","order":92,"canonicalText":"是月也，命工師效功，陳祭器，按度程，毋或作為淫巧以蕩上心。必功緻為上。物勒工名，以考其誠。功有不當，必行其罪，以窮其情。","sentenceIds":["li-ji_ch-6_p-92_s-1","li-ji_ch-6_p-92_s-2","li-ji_ch-6_p-92_s-3","li-ji_ch-6_p-92_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，命工師效功，陳祭器，按度程，毋或作為淫巧以蕩上心。必功緻為上。物勒工名，以考他的誠。功有不當，必行他的罪，以窮他的情。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 92 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，命工師效功，陳祭器，按度程，毋或作為淫巧以蕩上心」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，命工師效功，陳祭器，按度程，毋或作為淫巧以蕩……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-93","chapterId":"li-ji_ch-6","order":93,"canonicalText":"是月也，大飲烝。天子乃祈來年於天宗，大割祠於公社及門閭。臘先祖五祀，勞農以休息之。天子乃命將帥講武，習射御角力。","sentenceIds":["li-ji_ch-6_p-93_s-1","li-ji_ch-6_p-93_s-2","li-ji_ch-6_p-93_s-3","li-ji_ch-6_p-93_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，朝廷舉行盛大的「烝祭」冬祭與合飲典禮。天子在圜丘向上天日月星辰等「天宗」祈求來年風調雨順五穀豐登，在社稷壇與城門閭里大肆宰牲舉行盛大割牲祭祀。並在歲暮舉行隆重的「臘祭」，祭祀祖先神明與門、戶、井、灶、中溜等五祀之神，舉行盛宴犒勞體恤天下農民，讓辛苦耕耘一年的農夫休養生息。天子隨即命令將帥大臣講習武備陣法，演練射箭、駕車與角力搏擊等各類武藝。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 93 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，大飲烝」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，大飲烝。天子乃祈來年於天宗，大割祠於公社及門……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-94","chapterId":"li-ji_ch-6","order":94,"canonicalText":"是月也，乃命水虞漁師，收水泉池澤之賦。毋或敢侵削眾庶兆民，以為天子取怨於下。其有若此者，行罪無赦。","sentenceIds":["li-ji_ch-6_p-94_s-1","li-ji_ch-6_p-94_s-2","li-ji_ch-6_p-94_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，乃命水虞漁師，收水泉池澤的賦。毋或敢侵削眾庶兆民，以為天子取怨於下。他的有若此的人或禮儀規程與道崇高德行與品性修養規範制規範，行罪無赦。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 94 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，乃命水虞漁師，收水泉池澤之賦」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，乃命水虞漁師，收水泉池澤之賦。毋或敢侵削眾庶……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-95","chapterId":"li-ji_ch-6","order":95,"canonicalText":"孟冬行春令，則凍閉不密，地氣上泄，民多流亡。行夏令，則國多暴風，方冬不寒，蟄蟲復出。行秋令，則雪霜不時，小兵時起，土地侵削。","sentenceIds":["li-ji_ch-6_p-95_s-1","li-ji_ch-6_p-95_s-2","li-ji_ch-6_p-95_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"孟冬十月若是推行了春季的政令，嚴冬封凍閉藏之氣就會不夠嚴密堅固，地下潛藏的地氣就會過早向上宣泄，導致冬麥枯死、百姓多因饑寒流亡異鄉。若是推行了夏季的政令，國家境內多發狂暴風災，當入嚴冬反而氣候反常不寒，冬眠入土的蟄蟲重新破土而出。若是推行了秋季的政令，雪霜冰雪降臨失節不合時宜，邊境細小兵端衝突頻繁挑起，國家疆土面臨侵蝕削奪之患。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 95 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「孟冬行春令，則凍閉不密，地氣上泄，民多流亡」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「孟冬行春令，則凍閉不密，地氣上泄，民多流亡。行夏令，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-96","chapterId":"li-ji_ch-6","order":96,"canonicalText":"仲冬之月，日在鬥，昏東壁中，旦軫中。其日壬癸。其帝顓頊，其神玄冥。其蟲介。其音羽，律中黃鍾。其數六。其味鹹，其臭朽。其祀行，祭先腎。","sentenceIds":["li-ji_ch-6_p-96_s-1","li-ji_ch-6_p-96_s-2","li-ji_ch-6_p-96_s-3","li-ji_ch-6_p-96_s-4","li-ji_ch-6_p-96_s-5","li-ji_ch-6_p-96_s-6","li-ji_ch-6_p-96_s-7","li-ji_ch-6_p-96_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲冬的月，日在鬥，昏東壁中，旦軫中。他的日壬癸。他的帝顓頊，他的神玄冥。他的蟲介。他的音羽，律中黃鍾。他的數六。他的味鹹，他的臭朽。他的祀行，祭先腎。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 96 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「仲冬之月，日在鬥，昏東壁中，旦軫中」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「仲冬之月，日在鬥，昏東壁中，旦軫中。其日壬癸。其帝顓……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-97","chapterId":"li-ji_ch-6","order":97,"canonicalText":"冰益壯，地始坼。鶡旦不鳴，虎始交。","sentenceIds":["li-ji_ch-6_p-97_s-1","li-ji_ch-6_p-97_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲冬十一月，河湖之冰更加堅厚堅實，大地嚴寒開始凍裂開縫。求旦之鳥鶡旦不再啼鳴，深山之中的猛虎開始交尾繁育。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 97 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「冰益壯，地始坼」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「冰益壯，地始坼。鶡旦不鳴，虎始交。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-98","chapterId":"li-ji_ch-6","order":98,"canonicalText":"天子居玄堂大廟，乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄玉。食黍與彘，其器閎以奄。飭死事。命有司曰：土事毋作，慎毋發蓋，毋發室屋，及起大眾，以固而閉。地氣且泄，是謂發天地之房，諸蟄則死，民必疾疫，又隨以喪。命之曰暢月。","sentenceIds":["li-ji_ch-6_p-98_s-1","li-ji_ch-6_p-98_s-2","li-ji_ch-6_p-98_s-3","li-ji_ch-6_p-98_s-4","li-ji_ch-6_p-98_s-5","li-ji_ch-6_p-98_s-6"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲冬十一月之時，天子居住在明堂北面的正堂「玄堂大廟」之中。乘坐純黑玄路車駕，駕馭純黑鐵驪駿馬，車上載設純黑旗幟，身穿黑色深厚朝服，佩戴深黑玄玉。進食黍米與豬肉，所用器具皆寬宏深大而蓋口封閉掩藏。天子在此萬物凋零之月整飭籌辦送終死喪各項用度。告誡命令有司官員說：一切動土挖掘的土木之事嚴禁興起，切切不可隨意掘發挖開覆土堆蓋，不可拆除翻修房屋室舍，嚴禁徵調大規模民眾大興役作，務必使大地保持深厚凝固與閉塞封藏。如果在大寒之時妄動土木使地下陽氣泄露，這就叫作挖開了天地閉藏的秘房，地下的各類冬眠蟄蟲必將凍餒死絕，人間百姓亦必暴發嚴重的疫病疾疫，緊接著就會隨之引發人口死亡大喪。因此古人將這個陽氣在地下充盈充溢、嚴禁宣泄的月份命名為「暢月」。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 98 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天子居玄堂大廟，乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄玉」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天子居玄堂大廟，乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-99","chapterId":"li-ji_ch-6","order":99,"canonicalText":"是月也，命奄尹，申宮令，審門閭，謹房室，必重閉。省婦事毋得淫，雖有貴戚近習，毋有不禁。乃命大酋，秫稻必齊，麴蘗必時，湛熾必潔，水泉必香，陶器必良，火齊必得，兼用六物。大酋監之，毋有差貸。天子命有司祈祀四海大川名源淵澤井泉。","sentenceIds":["li-ji_ch-6_p-99_s-1","li-ji_ch-6_p-99_s-2","li-ji_ch-6_p-99_s-3","li-ji_ch-6_p-99_s-4","li-ji_ch-6_p-99_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，命令掌管宮禁內侍的「奄尹」，重申宮廷門禁條令，仔細巡查宮殿門閭，審慎巡視后妃房室，務必層層下鎖重重閉鎖。裁汰約束宮中婦女的遊玩雜事，嚴防產生任何淫亂驕奢之端，即便皇親國戚與君王寵近的近習權貴，也一律嚴格遵從門禁制度無所姑息豁免。隨後命令掌管釀酒的長官「大酋」，釀酒所用的黏稻黏秫原料必須純淨齊整，發酵所用的酒麴酒蘗必須合乎四時節氣，浸泡蒸煮穀物必須極其潔淨無瑕，釀造取水的水泉水源必須甘冽清香，盛酒發酵的陶器器皿必須質地堅良，控制火候溫熱的「火齊」調配必須精準得當，必須全面兼顧具備這六大釀酒法規。大酋長官親自監察督導釀酒工序，不可有絲毫差錯疏失與懈怠借貸。天子隨後派遣有司官員，誠敬祈禱祭祀四海大洋、名山大川、著名水脈源頭、深潭巨淵與名泉井水。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 99 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，命奄尹，申宮令，審門閭，謹房室，必重閉」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，命奄尹，申宮令，審門閭，謹房室，必重閉。省婦……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-100","chapterId":"li-ji_ch-6","order":100,"canonicalText":"是月也，農有不收藏積聚者、馬牛畜獸有放佚者，取之不詰。山林藪澤，有能取蔬食、田獵禽獸者，野虞教道之；其有相侵奪者，罪之不赦。","sentenceIds":["li-ji_ch-6_p-100_s-1","li-ji_ch-6_p-100_s-2","li-ji_ch-6_p-100_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，農有不收藏積聚的人或禮儀規程與道崇高德行與品性修養規範制規範、馬牛畜獸有放佚的人或禮儀規程與道崇高德行與品性修養規範制規範，取的不詰。山林藪澤，有能取蔬食、田獵禽獸的人或禮儀規程與道崇高德行與品性修養規範制規範，野虞教道的；他的有相侵奪的人或禮儀規程與道崇高德行與品性修養規範制規範，罪的不赦。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 100 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，農有不收藏積聚者、馬牛畜獸有放佚者，取之不詰」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，農有不收藏積聚者、馬牛畜獸有放佚者，取之不詰……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-101","chapterId":"li-ji_ch-6","order":101,"canonicalText":"是月也，日短至。陰陽爭，諸生蕩。君子齊戒，處必掩身。身欲寧，去聲色，禁耆欲。安形性，事欲靜，以待陰陽之所定。蕓始生，荔挺出，蚯螾結，麋角解，水泉動。日短至，則伐木，取竹箭。","sentenceIds":["li-ji_ch-6_p-101_s-1","li-ji_ch-6_p-101_s-2","li-ji_ch-6_p-101_s-3","li-ji_ch-6_p-101_s-4","li-ji_ch-6_p-101_s-5","li-ji_ch-6_p-101_s-6","li-ji_ch-6_p-101_s-7"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，日短至。陰陽爭，諸生蕩。具有道德修養之君子賢士人階層齊戒，處必掩身。身欲寧，去聲色，禁耆欲。安形性，事欲靜，以待陰陽的所定。蕓始生，荔挺出，蚯螾結，麋角解，水泉動。日短至，則伐木，取竹箭。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 101 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，日短至」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，日短至。陰陽爭，諸生蕩。君子齊戒，處必掩身。……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-102","chapterId":"li-ji_ch-6","order":102,"canonicalText":"是月也，可以罷官之無事、去器之無用者。塗闕廷門閭，築囹圄，此所以助天地之閉藏也。","sentenceIds":["li-ji_ch-6_p-102_s-1","li-ji_ch-6_p-102_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，可以罷官的無事、去器的無用的人或禮儀規程與道崇高德行與品性修養規範制規範。塗闕廷門閭，築囹圄，此所以助天地的閉藏啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 102 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，可以罷官之無事、去器之無用者」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，可以罷官之無事、去器之無用者。塗闕廷門閭，築……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-103","chapterId":"li-ji_ch-6","order":103,"canonicalText":"仲冬行夏令，則其國乃旱，氛霧冥冥，雷乃發聲。行秋令，則天時雨汁，瓜瓠不成，國有大兵。行春令，則蝗蟲為敗，水泉鹹竭，民多疥癘。","sentenceIds":["li-ji_ch-6_p-103_s-1","li-ji_ch-6_p-103_s-2","li-ji_ch-6_p-103_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仲冬十一月若是推行了夏季的政令，其國家便會暴發嚴重大旱乾旱，天地間陰霾妖霧瀰漫昏暗，寒冬臘月竟然反常震響雷聲。若是推行了秋季的政令，天時反常降下雨雪泥濘陰濕之水，瓜瓠等晚熟蔬果無法長成受凍腐爛，國家境內有重大兵戈戰事爆發。若是推行了春季的政令，蝗蟲害蟲滋生為害為患，山澤井泉水源全部乾涸枯竭，民間百姓多罹患頑固的疥瘡頑癬各類癘疾。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 103 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「仲冬行夏令，則其國乃旱，氛霧冥冥，雷乃發聲」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「仲冬行夏令，則其國乃旱，氛霧冥冥，雷乃發聲。行秋令，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-104","chapterId":"li-ji_ch-6","order":104,"canonicalText":"季冬之月，日在婺女，昏婁中，旦氐中。其日壬癸。其帝顓頊，其神玄冥。其蟲介。其音羽，律中大呂。其數六。其味鹹，其臭朽。其祀行，祭先腎。","sentenceIds":["li-ji_ch-6_p-104_s-1","li-ji_ch-6_p-104_s-2","li-ji_ch-6_p-104_s-3","li-ji_ch-6_p-104_s-4","li-ji_ch-6_p-104_s-5","li-ji_ch-6_p-104_s-6","li-ji_ch-6_p-104_s-7","li-ji_ch-6_p-104_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季冬的月，日在婺女，昏婁中，旦氐中。他的日壬癸。他的帝顓頊，他的神玄冥。他的蟲介。他的音羽，律中大呂。他的數六。他的味鹹，他的臭朽。他的祀行，祭先腎。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 104 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「季冬之月，日在婺女，昏婁中，旦氐中」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「季冬之月，日在婺女，昏婁中，旦氐中。其日壬癸。其帝顓……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-105","chapterId":"li-ji_ch-6","order":105,"canonicalText":"雁北鄉，鵲始巢。雉雊，雞乳。","sentenceIds":["li-ji_ch-6_p-105_s-1","li-ji_ch-6_p-105_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季冬十二月，感知春氣的大雁開始振翅向北返飛，喜鵲感知陽氣開始銜枝築巢。野雞高聲求偶長啼，家雞感應時令開始孵育雛雞。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 105 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「雁北鄉，鵲始巢」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「雁北鄉，鵲始巢。雉雊，雞乳。」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-106","chapterId":"li-ji_ch-6","order":106,"canonicalText":"天子居玄堂右個。乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄玉。食黍與彘，其器閎以奄。命有司大難，旁磔，出土牛，以送寒氣。徵鳥厲疾。乃畢山川之祀，及帝之大臣，天子神祇。","sentenceIds":["li-ji_ch-6_p-106_s-1","li-ji_ch-6_p-106_s-2","li-ji_ch-6_p-106_s-3","li-ji_ch-6_p-106_s-4","li-ji_ch-6_p-106_s-5","li-ji_ch-6_p-106_s-6"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季冬十二月之時，天子居住在明堂東北側的「玄堂右個」偏室之中。乘坐黑色玄路車駕，駕馭純黑鐵驪馬匹，車上插設純黑玄旗，身穿黑色禮服，佩戴深黑玄玉。進食黍米與豬肉，所使用的器具皆寬大宏敞而外加覆蓋。命令主管有司舉行盛大的逐疫「大儺」典禮，在城門四方宰割牲牲畜分裂肢體舉行「旁磔」之祭，堆塑陳列土製耕牛立於四門之外，以隆重送走殘冬陰冷寒氣、迎接初春生機。猛禽徵鳥因嚴寒感召而盤旋迅猛搏擊獵物。至此全面完成一年四季祭祀名山大川的盛典，以及祭祀上天五方上帝的大臣神靈，與天子祭祀之天地群神神祇。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 106 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「天子居玄堂右個」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「天子居玄堂右個。乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-107","chapterId":"li-ji_ch-6","order":107,"canonicalText":"是月也，命漁師始漁，天子親往，乃嘗魚，先薦寢廟。冰方盛，水澤腹堅。命取冰，冰以入。令告民，出五種。命農計耦耕事，修耒耜，具田器。命樂師大合吹而罷。乃命四監收秩薪柴，以共郊廟及百祀之薪燎。","sentenceIds":["li-ji_ch-6_p-107_s-1","li-ji_ch-6_p-107_s-2","li-ji_ch-6_p-107_s-3","li-ji_ch-6_p-107_s-4","li-ji_ch-6_p-107_s-5","li-ji_ch-6_p-107_s-6","li-ji_ch-6_p-107_s-7"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在這個月裡，命令掌管漁業的「漁師」開始在解凍之際捕魚，天子親自前往水澤觀看捕魚，並親口品嚐鮮魚美味，首先將新捕的鮮魚薦獻於祖先寢廟。此時隆冬冰凍正盛，湖泊水澤腹地堅厚如石。命令開冰窖採集天然厚冰，將晶瑩冰塊運入冰庫深處收藏。向全國百姓發布通告，取出預藏待播的五穀種籽進行翻曬檢視。命令農官審定核算開春二人協作「耦耕」的人力與農務，修繕打造犁鏵木耒鐵耜，完備修治各類田間農具。天子命令掌樂的樂師合奏各類吹奏樂器舉行「大合吹」年終音樂盛會，隨後宣布一年樂教禮畢休樂。隨即命令掌管山林的「四監」官員，依定額徵集收納供祭祀使用的柴薪柴草，以供應祭祀天地郊廟及天下百神祭祀所需的薪炭燎火。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 107 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，命漁師始漁，天子親往，乃嘗魚，先薦寢廟」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，命漁師始漁，天子親往，乃嘗魚，先薦寢廟。冰方……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-108","chapterId":"li-ji_ch-6","order":108,"canonicalText":"是月也，日窮於次，月窮於紀，星迴於天。數將幾終，歲且更始。專而農民，毋有所使。天子乃與公、卿、大夫，共飭國典，論時令，以待來歲之宜。乃命太史次諸侯之列，賦之犧牲，以共皇天、上帝、社稷之饗。乃命同姓之邦，共寢廟之芻豢。命宰歷卿大夫至於庶民土田之數，而賦犧牲，以共山林名川之祀。凡在天下九州之民者，無不鹹獻其力，以共皇天、上帝、社稷、寢廟、山林、名川之祀。","sentenceIds":["li-ji_ch-6_p-108_s-1","li-ji_ch-6_p-108_s-2","li-ji_ch-6_p-108_s-3","li-ji_ch-6_p-108_s-4","li-ji_ch-6_p-108_s-5","li-ji_ch-6_p-108_s-6","li-ji_ch-6_p-108_s-7","li-ji_ch-6_p-108_s-8"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"是月啊，日窮於次，月窮於紀，星迴於天。數將幾終，歲且更始。專而且農民，毋有所使。天子乃與公、卿、卿大夫貴族官員，共飭國典，論時令，以待來歲的宜。乃命太史次諸侯的列，賦的犧牲，以共皇天、上帝、社稷的饗。乃命同姓的邦，共寢廟的芻豢。命宰歷卿卿大夫貴族官員至於庶民土田的數，而且賦犧牲，以共山林名川的祀。凡在天下九州的民的人或禮儀規程與道崇高德行與品性修養規範制規範，無不鹹獻他的力，以共皇天、上帝、社稷、寢廟、山林、名川的祀。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 108 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是月也，日窮於次，月窮於紀，星迴於天」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是月也，日窮於次，月窮於紀，星迴於天。數將幾終，歲且……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-6_p-109","chapterId":"li-ji_ch-6","order":109,"canonicalText":"季冬行秋令，則白露早降，介蟲為妖，四鄙入保。行春令，則胎夭多傷，國多固疾，命之曰逆。行夏令，則水潦敗國，時雪不降，冰凍消釋。","sentenceIds":["li-ji_ch-6_p-109_s-1","li-ji_ch-6_p-109_s-2","li-ji_ch-6_p-109_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"季冬十二月若是推行了秋季的政令，嚴霜白露就會過早降臨凍害大地，介殼甲蟲繁衍滋生化為蟲害妖孽，四方邊鄙百姓被迫逃入保壘城堡躲避嚴寒與災禍。若是推行了春季的政令，懷孕的母獸與剛出生的幼畜多遭殘害傷亡，國家境內多流行久治不愈的頑疾痼疾，這種逆亂四時陰陽的現象稱為「逆」。若是推行了夏季的政令，連綿陰雨暴水就會沖毀淹沒國家城邑，應當應季飄落的祥雪遲遲不降，封凍的堅冰江河過早消融解凍。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈月令〉（第 109 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「季冬行秋令，則白露早降，介蟲為妖，四鄙入保」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「季冬行秋令，則白露早降，介蟲為妖，四鄙入保。行春令，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"li-ji_ch-6_p-1_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-1","order":1,"canonicalText":"孟春之月，日在營室，昏參中，旦尾中。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-1_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-1","order":2,"canonicalText":"其日甲乙。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-1_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-1","order":3,"canonicalText":"其帝大皞，其神句芒。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-1_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-1","order":4,"canonicalText":"其蟲鱗。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-1_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-1","order":5,"canonicalText":"其音角，律中大蔟。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-1_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-1","order":6,"canonicalText":"其數八。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-1_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-1","order":7,"canonicalText":"其味酸，其臭羶。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-1_s-8","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-1","order":8,"canonicalText":"其祀戶，祭先脾。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-2_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-2","order":1,"canonicalText":"東風解凍，蟄蟲始振，魚上冰，獺祭魚，鴻雁來。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-3_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-3","order":1,"canonicalText":"天子居青陽左個。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-3_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-3","order":2,"canonicalText":"乘鸞路，駕倉龍，載青旗，衣青衣，服倉玉，食麥與羊，其器疏以達。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-4_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-4","order":1,"canonicalText":"是月也，以立春。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-4_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-4","order":2,"canonicalText":"先立春三日，大史謁之天子曰：某日立春，盛德在木。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-4_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-4","order":3,"canonicalText":"天子乃齊。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-4_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-4","order":4,"canonicalText":"立春之日，天子親帥三公、九卿、諸侯、大夫以迎春於東郊。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-4_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-4","order":5,"canonicalText":"還反，賞公卿、諸侯、大夫於朝。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-4_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-4","order":6,"canonicalText":"命相佈德和令，行慶施惠，下及兆民。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-4_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-4","order":7,"canonicalText":"慶賜遂行，毋有不當。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-4_s-8","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-4","order":8,"canonicalText":"乃命大史守典奉法，司天日月星辰之行，宿離不貸，毋失經紀，以初為常。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-5_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-5","order":1,"canonicalText":"是月也，天子乃以元日祈穀於上帝。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-5_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-5","order":2,"canonicalText":"乃擇元辰，天子親載耒耜，措之參保介之御間，帥三公、九卿、諸侯、大夫，躬耕帝藉。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-5_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-5","order":3,"canonicalText":"天子三推，三公五推，卿諸侯九推。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-5_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-5","order":4,"canonicalText":"反，執爵於大寢，三公、九卿、諸侯、大夫皆御，命曰：勞酒。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-6_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-6","order":1,"canonicalText":"是月也，天氣下降，地氣上騰，天地和同，草木萌動。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-6_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-6","order":2,"canonicalText":"王命布農事，命田舍東郊，皆修封疆，審端經術。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-6_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-6","order":3,"canonicalText":"善相丘陵阪險原隰土地所宜，五穀所殖，以教道民，必躬親之。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-6_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-6","order":4,"canonicalText":"田事既飭，先定準直，農乃不惑。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-7_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-7","order":1,"canonicalText":"是月也，命樂正入學習舞。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-7_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-7","order":2,"canonicalText":"乃修祭典。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-7_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-7","order":3,"canonicalText":"命祀山林川澤，犧牲毋用牝。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-7_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-7","order":4,"canonicalText":"禁止伐木。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-7_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-7","order":5,"canonicalText":"毋覆巢，毋殺孩蟲、胎、夭、飛鳥。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-7_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-7","order":6,"canonicalText":"毋麑，毋卵。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-7_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-7","order":7,"canonicalText":"毋聚大眾，毋置城郭。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-7_s-8","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-7","order":8,"canonicalText":"掩骼埋胔。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-8_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-8","order":1,"canonicalText":"是月也，不可以稱兵，稱兵必天殃。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-8_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-8","order":2,"canonicalText":"兵戎不起，不可從我始。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-8_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-8","order":3,"canonicalText":"毋變天之道，毋絕地之理，毋亂人之紀。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-9_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-9","order":1,"canonicalText":"孟春行夏令，則雨水不時，草木蚤落，國時有恐。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-9_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-9","order":2,"canonicalText":"行秋令則其民大疫，猋風暴雨總至，藜莠蓬蒿並興。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-9_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-9","order":3,"canonicalText":"行冬令則水潦為敗，雪霜大摯，首種不入。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-10_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-10","order":1,"canonicalText":"仲春之月，日在奎，昏弧中，旦建星中。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-10_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-10","order":2,"canonicalText":"其日甲乙，其帝大皞，其神句芒。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-10_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-10","order":3,"canonicalText":"其蟲鱗。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-10_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-10","order":4,"canonicalText":"其音角，律中夾鐘。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-10_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-10","order":5,"canonicalText":"其數八。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-10_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-10","order":6,"canonicalText":"其味酸，其臭羶，其祀戶，祭先脾。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-11_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-11","order":1,"canonicalText":"始雨水，桃始華，倉庚鳴，鷹化為鳩。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-12_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-12","order":1,"canonicalText":"天子居青陽大廟，乘鸞路，駕倉龍，載青旗，衣青衣，服倉玉，食麥與羊，其器疏以達。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-13_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-13","order":1,"canonicalText":"是月也，安萌芽，養幼少，存諸孤。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-13_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-13","order":2,"canonicalText":"擇元日，命民社。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-13_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-13","order":3,"canonicalText":"命有司省囹圄，去桎梏，毋肆掠，止獄訟。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-14_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-14","order":1,"canonicalText":"是月也，玄鳥至。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-14_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-14","order":2,"canonicalText":"至之日，以大牢祠於高禖。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-14_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-14","order":3,"canonicalText":"天子親往，后妃帥九嬪御。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-14_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-14","order":4,"canonicalText":"乃禮天子所御，帶以弓韣，授以弓矢，於高禖之前。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-15_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-15","order":1,"canonicalText":"是月也，日夜分。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-15_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-15","order":2,"canonicalText":"雷乃發聲，始電，蟄蟲鹹動，啟戶始出。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-15_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-15","order":3,"canonicalText":"先雷三日，奮木鐸以令兆民曰：雷將發聲，有不戒其容止者，生子不備，必有兇災。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-15_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-15","order":4,"canonicalText":"日夜分，則同度量，鈞衡石，角鬥甬，正權概。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-16_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-16","order":1,"canonicalText":"是月也，耕者少舍。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-16_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-16","order":2,"canonicalText":"乃修闔扇，寢廟畢備。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-16_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-16","order":3,"canonicalText":"毋作大事，以妨農之事。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-17_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-17","order":1,"canonicalText":"是月也，毋竭川澤，毋漉陂池，毋焚山林。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-17_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-17","order":2,"canonicalText":"天子乃鮮羔開冰，先薦寢廟。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-17_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-17","order":3,"canonicalText":"上丁，命樂正習舞，釋菜。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-17_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-17","order":4,"canonicalText":"天子乃帥三公、九卿、諸侯、大夫親往視之。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-17_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-17","order":5,"canonicalText":"仲丁，又命樂正入學習舞。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-18_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-18","order":1,"canonicalText":"是月也，祀不用犧牲，用圭璧，更皮幣。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-19_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-19","order":1,"canonicalText":"仲春行秋令，則其國大水，寒氣總至，寇戎來徵。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-19_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-19","order":2,"canonicalText":"行冬令，則陽氣不勝，麥乃不熟，民多相掠。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-19_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-19","order":3,"canonicalText":"行夏令，則國乃大旱，暖氣早來，蟲螟為害。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-20_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-20","order":1,"canonicalText":"季春之月，日在胃，昏七星中，旦牽牛中。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-20_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-20","order":2,"canonicalText":"其日甲乙。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-20_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-20","order":3,"canonicalText":"其帝大皞，其神句芒。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-20_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-20","order":4,"canonicalText":"其蟲鱗。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-20_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-20","order":5,"canonicalText":"其音角，律中姑洗。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-20_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-20","order":6,"canonicalText":"其數八。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-20_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-20","order":7,"canonicalText":"其味酸，其臭羶。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-20_s-8","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-20","order":8,"canonicalText":"其祀戶，祭先脾。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-21_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-21","order":1,"canonicalText":"桐始華，田鼠化為鴽，虹始見，萍始生。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-22_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-22","order":1,"canonicalText":"天子居青陽右個，乘鸞路，駕倉龍，載青旗，衣青衣，服倉玉。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-22_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-22","order":2,"canonicalText":"食麥與羊，其器疏以達。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-23_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-23","order":1,"canonicalText":"是月也，天子乃薦鞠衣於先帝。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-23_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-23","order":2,"canonicalText":"命舟牧覆舟，五覆五反。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-23_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-23","order":3,"canonicalText":"乃告舟備具於天子焉，天子始乘舟。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-23_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-23","order":4,"canonicalText":"薦鮪於寢廟，乃為麥祈實。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-24_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-24","order":1,"canonicalText":"是月也，生氣方盛，陽氣發泄，句者畢出，萌者盡達。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-24_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-24","order":2,"canonicalText":"不可以內。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-24_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-24","order":3,"canonicalText":"天子佈德行惠，命有司發倉廩，賜貧窮，振乏絕，開府庫，出幣帛，周天下。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-24_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-24","order":4,"canonicalText":"勉諸侯，聘名士，禮賢者。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-25_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-25","order":1,"canonicalText":"是月也，命司空曰：時雨將降，下水上騰，循行國邑，周視原野，修利堤防，道達溝瀆，開通道路，毋有障塞。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-25_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-25","order":2,"canonicalText":"田獵罝罘、羅網、畢翳、餧獸之藥，毋出九門。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-26_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-26","order":1,"canonicalText":"是月也，命野虞毋伐桑柘。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-26_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-26","order":2,"canonicalText":"鳴鳩拂其羽，戴勝降於桑。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-26_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-26","order":3,"canonicalText":"具曲植籧筐。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-26_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-26","order":4,"canonicalText":"后妃齊戒，親東鄉躬桑。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-26_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-26","order":5,"canonicalText":"禁婦女毋觀，省婦使以勸蠶事。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-26_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-26","order":6,"canonicalText":"蠶事既登，分繭稱絲效功，以共郊廟之服，無有敢惰。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-27_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-27","order":1,"canonicalText":"是月也，命工師令百工審五庫之量：金鐵，皮革筋，角齒，羽箭幹，脂膠丹漆，毋或不良。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-27_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-27","order":2,"canonicalText":"百工鹹理，監工日號；","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-27_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-27","order":3,"canonicalText":"毋悖於時，毋或作為淫巧以蕩上心。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-28_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-28","order":1,"canonicalText":"是月之末，擇吉日，大合樂，天子乃率三公、九卿、諸侯、大夫親往視之。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-29_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-29","order":1,"canonicalText":"是月也，乃合累牛騰馬，遊牝於牧。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-29_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-29","order":2,"canonicalText":"犧牲駒犢，舉，書其數。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-29_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-29","order":3,"canonicalText":"命國難，九門磔攘，以畢春氣。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-30_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-30","order":1,"canonicalText":"季春行冬令，則寒氣時發，草木皆肅，國有大恐。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-30_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-30","order":2,"canonicalText":"行夏令，則民多疾疫，時雨不降，山林不收。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-30_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-30","order":3,"canonicalText":"行秋令，則天多沉陰，淫雨蚤降，兵革並起。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-31_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-31","order":1,"canonicalText":"孟夏之月，日在畢，昏翼中，旦婺女中。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-31_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-31","order":2,"canonicalText":"其日丙丁。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-31_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-31","order":3,"canonicalText":"其帝炎帝，其神祝融。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-31_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-31","order":4,"canonicalText":"其蟲羽。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-31_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-31","order":5,"canonicalText":"其音徵，律中中呂。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-31_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-31","order":6,"canonicalText":"其數七。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-31_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-31","order":7,"canonicalText":"其味苦，其臭焦。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-31_s-8","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-31","order":8,"canonicalText":"其祀竈，祭先肺。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-32_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-32","order":1,"canonicalText":"螻蟈鳴，蚯螾出，王瓜生，苦菜秀。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-33_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-33","order":1,"canonicalText":"天子居明堂左個，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤玉。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-33_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-33","order":2,"canonicalText":"食菽與雞，其器高以粗。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-34_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-34","order":1,"canonicalText":"是月也，以立夏。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-34_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-34","order":2,"canonicalText":"先立夏三日，大史謁之天子曰：某日立夏，盛德在火。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-34_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-34","order":3,"canonicalText":"天子乃齊。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-34_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-34","order":4,"canonicalText":"立夏之日，天子親帥三公、九卿、大夫以迎夏於南郊。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-34_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-34","order":5,"canonicalText":"還反，行賞，封諸侯。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-34_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-34","order":6,"canonicalText":"慶賜遂行，無不欣說。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-34_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-34","order":7,"canonicalText":"乃命樂師，習合禮樂。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-34_s-8","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-34","order":8,"canonicalText":"命太尉，贊桀俊，遂賢良，舉長大，行爵出祿，必當其位。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-35_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-35","order":1,"canonicalText":"是月也，繼長增高，毋有壞墮，毋起土功，毋發大眾，毋伐大樹。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-36_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-36","order":1,"canonicalText":"是月也，天子始絺。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-36_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-36","order":2,"canonicalText":"命野虞出行田原，為天子勞農勸民，毋或失時。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-36_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-36","order":3,"canonicalText":"命司徒巡行縣鄙，命農勉作，毋休于都。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-37_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-37","order":1,"canonicalText":"是月也，驅獸毋害五穀，毋大田獵。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-37_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-37","order":2,"canonicalText":"農乃登麥，天子乃以彘嘗麥，先薦寢廟。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-38_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-38","order":1,"canonicalText":"是月也，聚畜百藥。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-38_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-38","order":2,"canonicalText":"靡草死，麥秋至。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-38_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-38","order":3,"canonicalText":"斷薄刑，決小罪，出輕系。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-38_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-38","order":4,"canonicalText":"蠶事畢，后妃獻繭。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-38_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-38","order":5,"canonicalText":"乃收繭稅，以桑為均，貴賤長幼如一，以給郊廟之服。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-39_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-39","order":1,"canonicalText":"是月也，天子飲酎，用禮樂。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-40_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-40","order":1,"canonicalText":"孟夏行秋令，則苦雨數來，五穀不滋，四鄙入保。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-40_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-40","order":2,"canonicalText":"行冬令，則草木蚤枯，後乃大水，敗其城郭。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-40_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-40","order":3,"canonicalText":"行春令，則蝗蟲為災，暴風來格，秀草不實。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-41_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-41","order":1,"canonicalText":"仲夏之月，日在東井，昏亢中，旦危中。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-41_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-41","order":2,"canonicalText":"其日丙丁。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-41_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-41","order":3,"canonicalText":"其帝炎帝，其神祝融。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-41_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-41","order":4,"canonicalText":"其蟲羽。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-41_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-41","order":5,"canonicalText":"其音徵，律中蕤賓。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-41_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-41","order":6,"canonicalText":"其數七。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-41_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-41","order":7,"canonicalText":"其味苦，其臭焦。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-41_s-8","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-41","order":8,"canonicalText":"其祀竈，祭先肺。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-42_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-42","order":1,"canonicalText":"小暑至，螳蜋生。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-42_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-42","order":2,"canonicalText":"鵙始鳴，反舌無聲。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-43_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-43","order":1,"canonicalText":"天子居明堂太廟，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤玉，食菽與雞，其器高以粗。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-43_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-43","order":2,"canonicalText":"養壯佼。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-44_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-44","order":1,"canonicalText":"是月也，命樂師修鞀鞞鼓，均琴瑟管簫，執干戚戈羽，調竽笙篪簧，飭鐘磬柷敔。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-44_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-44","order":2,"canonicalText":"命有司為民祈祀山川百源，大雩帝，用盛樂。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-44_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-44","order":3,"canonicalText":"乃命百縣，雩祀百辟卿士有益於民者，以祈穀實。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-44_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-44","order":4,"canonicalText":"農乃登黍。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-45_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-45","order":1,"canonicalText":"是月也，天子乃以雛嘗黍，羞以含桃，先薦寢廟。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-45_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-45","order":2,"canonicalText":"令民毋艾藍以染，毋燒灰，毋暴布。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-45_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-45","order":3,"canonicalText":"門閭毋閉，關市毋索。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-45_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-45","order":4,"canonicalText":"挺重囚，益其食。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-45_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-45","order":5,"canonicalText":"遊牝別羣，則縶騰駒，班馬政。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-46_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-46","order":1,"canonicalText":"是月也，日長至，陰陽爭，死生分。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-46_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-46","order":2,"canonicalText":"君子齊戒，處必掩身，毋躁。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-46_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-46","order":3,"canonicalText":"止聲色，毋或進。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-46_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-46","order":4,"canonicalText":"薄滋味，毋致和。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-46_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-46","order":5,"canonicalText":"節嗜慾，定心氣，百官靜事毋刑，以定晏陰之所成。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-46_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-46","order":6,"canonicalText":"鹿角解，蟬始鳴。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-46_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-46","order":7,"canonicalText":"半夏生，木堇榮。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-47_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-47","order":1,"canonicalText":"是月也，毋用火南方。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-47_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-47","order":2,"canonicalText":"可以居高明，可以遠眺望，可以升山陵，可以處臺榭。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-48_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-48","order":1,"canonicalText":"仲夏行冬令，則雹凍傷穀，道路不通，暴兵來至。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-48_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-48","order":2,"canonicalText":"行春令，則五穀晚熟，百螣時起，其國乃饑。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-48_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-48","order":3,"canonicalText":"行秋令，則草木零落，果實早成，民殃於疫。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-49_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-49","order":1,"canonicalText":"季夏之月，日在柳，昏火中，旦奎中。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-49_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-49","order":2,"canonicalText":"其日丙丁。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-49_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-49","order":3,"canonicalText":"其帝炎帝，其神祝融。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-49_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-49","order":4,"canonicalText":"其蟲羽。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-49_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-49","order":5,"canonicalText":"其音徵，律中林鐘。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-49_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-49","order":6,"canonicalText":"其數七。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-49_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-49","order":7,"canonicalText":"其味苦，其臭焦。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-49_s-8","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-49","order":8,"canonicalText":"其祀竈，祭先肺。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-50_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-50","order":1,"canonicalText":"溫風始至，蟋蟀居壁，鷹乃學習，腐草為螢。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-51_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-51","order":1,"canonicalText":"天子居明堂右個，乘朱路，駕赤騮，載赤旗，衣朱衣，服赤玉。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-51_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-51","order":2,"canonicalText":"食菽與雞，其器高以粗。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-51_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-51","order":3,"canonicalText":"命漁師伐蛟取鼉，登龜取黿。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-51_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-51","order":4,"canonicalText":"命澤人納材葦。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-52_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-52","order":1,"canonicalText":"是月也，命四監大合百縣之秩芻，以養犧牲。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-52_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-52","order":2,"canonicalText":"令民無不鹹出其力，以共皇天上帝名山大川四方之神，以祠宗廟社稷之靈，以為民祈福。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-53_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-53","order":1,"canonicalText":"是月也，命婦官染採，黼黻文章，必以法故，無或差貸。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-53_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-53","order":2,"canonicalText":"黑黃倉赤，莫不質良，毋敢詐偽，以給郊廟祭祀之服，以為旗章，以別貴賤等給之度。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-54_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-54","order":1,"canonicalText":"是月也，樹木方盛，乃命虞人入山行木，毋有斬伐。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-54_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-54","order":2,"canonicalText":"不可以興土功，不可以合諸侯，不可以起兵動眾，毋舉大事，以搖養氣。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-54_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-54","order":3,"canonicalText":"毋發令而待，以妨神農之事也。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-54_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-54","order":4,"canonicalText":"水潦盛昌，神農將持功，舉大事則有天殃。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-55_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-55","order":1,"canonicalText":"是月也，土潤溽暑，大雨時行，燒薙行水，利以殺草，如以熱湯。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-55_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-55","order":2,"canonicalText":"可以糞田疇，可以美土強。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-56_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-56","order":1,"canonicalText":"季夏行春令，則穀實鮮落，國多風咳，民乃遷徙。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-56_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-56","order":2,"canonicalText":"行秋令，則丘隰水潦，禾稼不熟，乃多女災。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-56_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-56","order":3,"canonicalText":"行冬令，則風寒不時，鷹隼蚤鷙，四鄙入保。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-57_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-57","order":1,"canonicalText":"中央土。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-57_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-57","order":2,"canonicalText":"其日戊己。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-57_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-57","order":3,"canonicalText":"其帝黃帝，其神后土。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-57_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-57","order":4,"canonicalText":"其蟲裸，其音宮，律中黃鐘之宮。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-57_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-57","order":5,"canonicalText":"其數五。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-57_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-57","order":6,"canonicalText":"其味甘，其臭香。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-57_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-57","order":7,"canonicalText":"其祠中溜，祭先心。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-58_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-58","order":1,"canonicalText":"天子居大廟大室，乘大路，駕黃騮，載黃旗，衣黃衣，服黃玉，食稷與牛，其器圜以閎。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-59_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-59","order":1,"canonicalText":"孟秋之月，日在翼，昏建星中，旦畢中。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-59_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-59","order":2,"canonicalText":"其日庚辛。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-59_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-59","order":3,"canonicalText":"其帝少皞，其神蓐收。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-59_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-59","order":4,"canonicalText":"其蟲毛。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-59_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-59","order":5,"canonicalText":"其音商，律中夷則。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-59_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-59","order":6,"canonicalText":"其數九。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-59_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-59","order":7,"canonicalText":"其味辛，其臭腥。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-59_s-8","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-59","order":8,"canonicalText":"其祀門，祭先肝。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-60_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-60","order":1,"canonicalText":"涼風至，白露降，寒蟬鳴。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-60_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-60","order":2,"canonicalText":"鷹乃祭鳥，用始行戮。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-61_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-61","order":1,"canonicalText":"天子居總章左個，乘戎路，駕白駱，載白旗，衣白衣，服白玉，食麻與犬，其器廉以深。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-62_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-62","order":1,"canonicalText":"是月也，以立秋。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-62_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-62","order":2,"canonicalText":"先立秋三日，大史謁之天子曰：某日立秋，盛德在金。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-62_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-62","order":3,"canonicalText":"天子乃齊。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-62_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-62","order":4,"canonicalText":"立秋之日，天子親帥三公、九卿、諸侯、大夫，以迎秋於西郊。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-62_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-62","order":5,"canonicalText":"還反，賞軍帥武人於朝。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-62_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-62","order":6,"canonicalText":"天子乃命將帥，選士厲兵，簡練桀俊，專任有功，以徵不義。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-62_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-62","order":7,"canonicalText":"詰誅暴慢，以明好惡，順彼遠方。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-63_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-63","order":1,"canonicalText":"是月也，命有司修法制，繕囹圄，具桎梏，禁止奸，慎罪邪，務搏執。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-63_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-63","order":2,"canonicalText":"命理瞻傷，察創，視折，審斷。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-63_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-63","order":3,"canonicalText":"決獄訟，必端平。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-63_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-63","order":4,"canonicalText":"戮有罪，嚴斷刑。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-63_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-63","order":5,"canonicalText":"天地始肅，不可以贏。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-64_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-64","order":1,"canonicalText":"是月也，農乃登穀。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-64_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-64","order":2,"canonicalText":"天子嘗新，先薦寢廟。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-64_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-64","order":3,"canonicalText":"命百官，始收斂。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-64_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-64","order":4,"canonicalText":"完堤防，謹壅塞，以備水潦。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-64_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-64","order":5,"canonicalText":"修宮室，壞墻垣，補城郭。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-65_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-65","order":1,"canonicalText":"是月也，毋以封諸侯、立大官。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-65_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-65","order":2,"canonicalText":"毋以割地、行大使、出大幣。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-66_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-66","order":1,"canonicalText":"孟秋行冬令，則陰氣大勝，介蟲敗穀，戎兵乃來。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-66_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-66","order":2,"canonicalText":"行春令，則其國乃旱，陽氣復還，五穀無實。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-66_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-66","order":3,"canonicalText":"行夏令，則國多火災，寒熱不節，民多瘧疾。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-67_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-67","order":1,"canonicalText":"仲秋之月，日在角，昏牽牛中，旦觜觿中。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-67_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-67","order":2,"canonicalText":"其日庚辛，其帝少皞，其神蓐收。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-67_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-67","order":3,"canonicalText":"其蟲毛。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-67_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-67","order":4,"canonicalText":"其音商，律中南呂。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-67_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-67","order":5,"canonicalText":"其數九。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-67_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-67","order":6,"canonicalText":"其味辛，其臭腥。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-67_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-67","order":7,"canonicalText":"其祀門，祭先肝。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-68_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-68","order":1,"canonicalText":"盲風至，鴻雁來，玄鳥歸，羣鳥養羞。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-69_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-69","order":1,"canonicalText":"天子居總章大廟，乘戎路，駕白駱，載白旗，衣白衣，服白玉，食麻與犬，其器廉以深。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-70_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-70","order":1,"canonicalText":"是月也，養衰老，授几杖，行糜粥飲食。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-70_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-70","order":2,"canonicalText":"乃命司服，具飭衣裳，文繡有恆，制有小大，度有長短。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-70_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-70","order":3,"canonicalText":"衣服有量，必循其故，冠帶有常。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-70_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-70","order":4,"canonicalText":"乃命有司，申嚴百刑，斬殺必當，毋或枉橈。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-70_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-70","order":5,"canonicalText":"枉橈不當，反受其殃。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-71_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-71","order":1,"canonicalText":"是月也，乃命宰祝，循行犧牲，視全具，案芻豢，瞻肥瘠，察物色。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-71_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-71","order":2,"canonicalText":"必比類，量小大，視長短，皆中度。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-71_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-71","order":3,"canonicalText":"五者備當，上帝其饗。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-71_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-71","order":4,"canonicalText":"天子乃難，以達秋氣。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-71_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-71","order":5,"canonicalText":"以犬嘗麻，先薦寢廟。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-72_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-72","order":1,"canonicalText":"是月也，可以築城郭，建都邑，穿竇窖，修囷倉。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-72_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-72","order":2,"canonicalText":"乃命有司，趣民收斂，務畜菜，多積聚。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-72_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-72","order":3,"canonicalText":"乃勸種麥，毋或失時。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-72_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-72","order":4,"canonicalText":"其有失時，行罪無疑。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-73_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-73","order":1,"canonicalText":"是月也，日夜分，雷始收聲。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-73_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-73","order":2,"canonicalText":"蟄蟲壞戶，殺氣浸盛，陽氣日衰，水始涸。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-73_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-73","order":3,"canonicalText":"日夜分，則同度量，平權衡，正鈞石，角鬥甬。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-74_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-74","order":1,"canonicalText":"是月也，易關市，來商旅，納貨賄，以便民事。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-74_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-74","order":2,"canonicalText":"四方來集，遠鄉皆至，則財不匱，上無乏用，百事乃遂。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-74_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-74","order":3,"canonicalText":"凡舉大事，毋逆大數，必順其時，慎因其類。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-75_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-75","order":1,"canonicalText":"仲秋行春令，則秋雨不降，草木生榮，國乃有恐。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-75_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-75","order":2,"canonicalText":"行夏令，則其國乃旱，蟄蟲不藏，五穀復生。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-75_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-75","order":3,"canonicalText":"行冬令，則風災數起，收雷先行，草木蚤死。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-76_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-76","order":1,"canonicalText":"季秋之月，日在房，昏虛中，旦柳中。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-76_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-76","order":2,"canonicalText":"其日庚辛。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-76_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-76","order":3,"canonicalText":"其帝少皞，其神蓐收。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-76_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-76","order":4,"canonicalText":"其蟲毛。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-76_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-76","order":5,"canonicalText":"其音商，律中無射。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-76_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-76","order":6,"canonicalText":"其數九。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-76_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-76","order":7,"canonicalText":"其味辛，其臭腥。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-76_s-8","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-76","order":8,"canonicalText":"其祀門，祭先肝。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-77_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-77","order":1,"canonicalText":"鴻雁來賓，爵入大水為蛤。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-77_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-77","order":2,"canonicalText":"鞠有黃華，豺乃祭獸戮禽。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-78_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-78","order":1,"canonicalText":"天子居總章右個，乘戎路，駕白駱，載白旗，衣白衣，服白玉。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-78_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-78","order":2,"canonicalText":"食麻與犬，其器廉以深。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-79_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-79","order":1,"canonicalText":"是月也，申嚴號令。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-79_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-79","order":2,"canonicalText":"命百官貴賤無不務內，以會天地之藏，無有宣出。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-79_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-79","order":3,"canonicalText":"乃命冢宰，農事備收，舉五穀之要，藏帝藉之收於神倉，祗敬必飭。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-80_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-80","order":1,"canonicalText":"是月也，霜始降，則百工休。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-80_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-80","order":2,"canonicalText":"乃命有司曰：寒氣總至，民力不堪，其皆入室。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-80_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-80","order":3,"canonicalText":"上丁，命樂正入學習吹。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-81_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-81","order":1,"canonicalText":"是月也，大饗帝、嘗，犧牲告備於天子。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-81_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-81","order":2,"canonicalText":"合諸侯，制百縣，為來歲受朔日，與諸侯所稅於民輕重之法，貢職之數，以遠近土地所宜為度，以給郊廟之事，無有所私。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-82_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-82","order":1,"canonicalText":"是月也，天子乃教於田獵，以習五戎，班馬政。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-82_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-82","order":2,"canonicalText":"命僕及七騶鹹駕，載旌旐，授車以級，整設於屏外。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-82_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-82","order":3,"canonicalText":"司徒搢撲，北面誓之。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-82_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-82","order":4,"canonicalText":"天子乃厲飾，執弓挾矢以獵，命主祠祭禽於四方。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-83_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-83","order":1,"canonicalText":"是月也，草木黃落，乃伐薪為炭。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-83_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-83","order":2,"canonicalText":"蟄蟲鹹俯在內，皆墐其戶。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-83_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-83","order":3,"canonicalText":"乃趣獄刑，毋留有罪。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-83_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-83","order":4,"canonicalText":"收祿秩之不當、供養之不宜者。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-84_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-84","order":1,"canonicalText":"是月也，天子乃以犬嘗稻，先薦寢廟。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-85_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-85","order":1,"canonicalText":"季秋行夏令，則其國大水，冬藏殃敗，民多鼽嚏。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-85_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-85","order":2,"canonicalText":"行冬令，則國多盜賊，邊境不寧，土地分裂。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-85_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-85","order":3,"canonicalText":"行春令，則暖風來至，民氣解惰，師興不居。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-86_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-86","order":1,"canonicalText":"孟冬之月，日在尾，昏危中，旦七星中。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-86_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-86","order":2,"canonicalText":"其日壬癸。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-86_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-86","order":3,"canonicalText":"其帝顓頊，其神玄冥。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-86_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-86","order":4,"canonicalText":"其蟲介。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-86_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-86","order":5,"canonicalText":"其音羽，律中應鐘。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-86_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-86","order":6,"canonicalText":"其數六。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-86_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-86","order":7,"canonicalText":"其味鹹，其臭朽。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-86_s-8","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-86","order":8,"canonicalText":"其祀行，祭先腎。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-87_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-87","order":1,"canonicalText":"水始冰，地始凍。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-87_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-87","order":2,"canonicalText":"雉入大水為蜃。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-87_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-87","order":3,"canonicalText":"虹藏不見。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-88_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-88","order":1,"canonicalText":"天子居玄堂左個，乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄玉，食黍與彘，其器閎以奄。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-89_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-89","order":1,"canonicalText":"是月也，以立冬。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-89_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-89","order":2,"canonicalText":"先立冬三日，太史謁之天子曰：某日立冬，盛德在水。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-89_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-89","order":3,"canonicalText":"天子乃齊。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-89_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-89","order":4,"canonicalText":"立冬之日，天子親帥三公、九卿、大夫以迎冬於北郊，還反，賞死事，恤孤寡。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-90_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-90","order":1,"canonicalText":"是月也，命大史釁龜策，佔兆審卦吉凶，是察阿黨，則罪無有掩蔽。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-91_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-91","order":1,"canonicalText":"是月也，天子始裘。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-91_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-91","order":2,"canonicalText":"命有司曰：天氣上騰，地氣下降，天地不通，閉塞而成冬。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-91_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-91","order":3,"canonicalText":"命百官謹蓋藏。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-91_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-91","order":4,"canonicalText":"命司徒循行積聚，無有不斂。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-91_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-91","order":5,"canonicalText":"壞城郭，戒門閭，修鍵閉，慎管龠，固封疆，備邊竟，完要塞，謹關梁，塞徯徑。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-91_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-91","order":6,"canonicalText":"飭喪紀，辨衣裳，審棺槨之厚薄，塋丘壟之大小、高卑、厚薄之度，貴賤之等級。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-92_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-92","order":1,"canonicalText":"是月也，命工師效功，陳祭器，按度程，毋或作為淫巧以蕩上心。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-92_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-92","order":2,"canonicalText":"必功緻為上。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-92_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-92","order":3,"canonicalText":"物勒工名，以考其誠。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-92_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-92","order":4,"canonicalText":"功有不當，必行其罪，以窮其情。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-93_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-93","order":1,"canonicalText":"是月也，大飲烝。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-93_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-93","order":2,"canonicalText":"天子乃祈來年於天宗，大割祠於公社及門閭。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-93_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-93","order":3,"canonicalText":"臘先祖五祀，勞農以休息之。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-93_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-93","order":4,"canonicalText":"天子乃命將帥講武，習射御角力。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-94_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-94","order":1,"canonicalText":"是月也，乃命水虞漁師，收水泉池澤之賦。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-94_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-94","order":2,"canonicalText":"毋或敢侵削眾庶兆民，以為天子取怨於下。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-94_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-94","order":3,"canonicalText":"其有若此者，行罪無赦。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-95_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-95","order":1,"canonicalText":"孟冬行春令，則凍閉不密，地氣上泄，民多流亡。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-95_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-95","order":2,"canonicalText":"行夏令，則國多暴風，方冬不寒，蟄蟲復出。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-95_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-95","order":3,"canonicalText":"行秋令，則雪霜不時，小兵時起，土地侵削。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-96_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-96","order":1,"canonicalText":"仲冬之月，日在鬥，昏東壁中，旦軫中。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-96_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-96","order":2,"canonicalText":"其日壬癸。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-96_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-96","order":3,"canonicalText":"其帝顓頊，其神玄冥。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-96_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-96","order":4,"canonicalText":"其蟲介。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-96_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-96","order":5,"canonicalText":"其音羽，律中黃鍾。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-96_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-96","order":6,"canonicalText":"其數六。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-96_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-96","order":7,"canonicalText":"其味鹹，其臭朽。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-96_s-8","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-96","order":8,"canonicalText":"其祀行，祭先腎。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-97_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-97","order":1,"canonicalText":"冰益壯，地始坼。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-97_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-97","order":2,"canonicalText":"鶡旦不鳴，虎始交。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-98_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-98","order":1,"canonicalText":"天子居玄堂大廟，乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄玉。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-98_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-98","order":2,"canonicalText":"食黍與彘，其器閎以奄。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-98_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-98","order":3,"canonicalText":"飭死事。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-98_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-98","order":4,"canonicalText":"命有司曰：土事毋作，慎毋發蓋，毋發室屋，及起大眾，以固而閉。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-98_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-98","order":5,"canonicalText":"地氣且泄，是謂發天地之房，諸蟄則死，民必疾疫，又隨以喪。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-98_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-98","order":6,"canonicalText":"命之曰暢月。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-99_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-99","order":1,"canonicalText":"是月也，命奄尹，申宮令，審門閭，謹房室，必重閉。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-99_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-99","order":2,"canonicalText":"省婦事毋得淫，雖有貴戚近習，毋有不禁。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-99_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-99","order":3,"canonicalText":"乃命大酋，秫稻必齊，麴蘗必時，湛熾必潔，水泉必香，陶器必良，火齊必得，兼用六物。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-99_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-99","order":4,"canonicalText":"大酋監之，毋有差貸。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-99_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-99","order":5,"canonicalText":"天子命有司祈祀四海大川名源淵澤井泉。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-100_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-100","order":1,"canonicalText":"是月也，農有不收藏積聚者、馬牛畜獸有放佚者，取之不詰。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-100_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-100","order":2,"canonicalText":"山林藪澤，有能取蔬食、田獵禽獸者，野虞教道之；","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-100_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-100","order":3,"canonicalText":"其有相侵奪者，罪之不赦。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-101_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-101","order":1,"canonicalText":"是月也，日短至。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-101_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-101","order":2,"canonicalText":"陰陽爭，諸生蕩。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-101_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-101","order":3,"canonicalText":"君子齊戒，處必掩身。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-101_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-101","order":4,"canonicalText":"身欲寧，去聲色，禁耆欲。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-101_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-101","order":5,"canonicalText":"安形性，事欲靜，以待陰陽之所定。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-101_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-101","order":6,"canonicalText":"蕓始生，荔挺出，蚯螾結，麋角解，水泉動。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-101_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-101","order":7,"canonicalText":"日短至，則伐木，取竹箭。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-102_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-102","order":1,"canonicalText":"是月也，可以罷官之無事、去器之無用者。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-102_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-102","order":2,"canonicalText":"塗闕廷門閭，築囹圄，此所以助天地之閉藏也。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-103_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-103","order":1,"canonicalText":"仲冬行夏令，則其國乃旱，氛霧冥冥，雷乃發聲。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-103_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-103","order":2,"canonicalText":"行秋令，則天時雨汁，瓜瓠不成，國有大兵。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-103_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-103","order":3,"canonicalText":"行春令，則蝗蟲為敗，水泉鹹竭，民多疥癘。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-104_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-104","order":1,"canonicalText":"季冬之月，日在婺女，昏婁中，旦氐中。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-104_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-104","order":2,"canonicalText":"其日壬癸。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-104_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-104","order":3,"canonicalText":"其帝顓頊，其神玄冥。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-104_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-104","order":4,"canonicalText":"其蟲介。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-104_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-104","order":5,"canonicalText":"其音羽，律中大呂。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-104_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-104","order":6,"canonicalText":"其數六。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-104_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-104","order":7,"canonicalText":"其味鹹，其臭朽。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-104_s-8","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-104","order":8,"canonicalText":"其祀行，祭先腎。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-105_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-105","order":1,"canonicalText":"雁北鄉，鵲始巢。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-105_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-105","order":2,"canonicalText":"雉雊，雞乳。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-106_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-106","order":1,"canonicalText":"天子居玄堂右個。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-106_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-106","order":2,"canonicalText":"乘玄路，駕鐵驪，載玄旗，衣黑衣，服玄玉。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-106_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-106","order":3,"canonicalText":"食黍與彘，其器閎以奄。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-106_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-106","order":4,"canonicalText":"命有司大難，旁磔，出土牛，以送寒氣。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-106_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-106","order":5,"canonicalText":"徵鳥厲疾。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-106_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-106","order":6,"canonicalText":"乃畢山川之祀，及帝之大臣，天子神祇。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-107_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-107","order":1,"canonicalText":"是月也，命漁師始漁，天子親往，乃嘗魚，先薦寢廟。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-107_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-107","order":2,"canonicalText":"冰方盛，水澤腹堅。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-107_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-107","order":3,"canonicalText":"命取冰，冰以入。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-107_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-107","order":4,"canonicalText":"令告民，出五種。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-107_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-107","order":5,"canonicalText":"命農計耦耕事，修耒耜，具田器。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-107_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-107","order":6,"canonicalText":"命樂師大合吹而罷。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-107_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-107","order":7,"canonicalText":"乃命四監收秩薪柴，以共郊廟及百祀之薪燎。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-108_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-108","order":1,"canonicalText":"是月也，日窮於次，月窮於紀，星迴於天。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-108_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-108","order":2,"canonicalText":"數將幾終，歲且更始。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-108_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-108","order":3,"canonicalText":"專而農民，毋有所使。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-108_s-4","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-108","order":4,"canonicalText":"天子乃與公、卿、大夫，共飭國典，論時令，以待來歲之宜。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-108_s-5","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-108","order":5,"canonicalText":"乃命太史次諸侯之列，賦之犧牲，以共皇天、上帝、社稷之饗。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-108_s-6","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-108","order":6,"canonicalText":"乃命同姓之邦，共寢廟之芻豢。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-108_s-7","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-108","order":7,"canonicalText":"命宰歷卿大夫至於庶民土田之數，而賦犧牲，以共山林名川之祀。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-108_s-8","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-108","order":8,"canonicalText":"凡在天下九州之民者，無不鹹獻其力，以共皇天、上帝、社稷、寢廟、山林、名川之祀。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-109_s-1","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-109","order":1,"canonicalText":"季冬行秋令，則白露早降，介蟲為妖，四鄙入保。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-109_s-2","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-109","order":2,"canonicalText":"行春令，則胎夭多傷，國多固疾，命之曰逆。","chunks":[],"tags":[]},{"id":"li-ji_ch-6_p-109_s-3","workId":"li-ji","chapterId":"li-ji_ch-6","passageId":"li-ji_ch-6_p-109","order":3,"canonicalText":"行夏令，則水潦敗國，時雪不降，冰凍消釋。","chunks":[],"tags":[]}]}');export{i as default};
